window.NAM_METHOD_RECORDS = [{"id":"TM2012-06","shortName":"Bhas 42 CTA","title":"Cell Transformation Assay Based on the Bhas 42 Cell Line","organisation":"EURL ECVAM - European Union","description":"The in vitro CTA using Bhas 42 cell line is aimed at detecting the carcinogenic potential of chemicals. The assay is based on the change of the phenotypic features of cells undergoing the first steps of the conversion from normal cells to neoplastic-like cell foci with oncogenic properties. Carcinogenesis is a complex multistage process by which normal cells are transformed into cancer cells characterised by an accumulation of changes at the cellular, genetic and epigenetic level. In vitro CTAs such as the Bhas 42 CTA have been shown to recapitulate a multistage process that closely models some stages of in vivo carcinogenesis. Cell transformation in all the systems studied to-date involves changes at each stage in order for progression to the next stage in the transformation process to occur. A minimum of four phenotypic stages appears to be involved in cell transformation. These include (from primary to fully malignant cells): a block in cellular differentiation, acquisition of immortality, characterised by unlimited lifespan, an aneuploidy karyotype and a decreased genetic stability; acquisition of tumorigenicity, which is closely associated with the in vitro phenotypes of foci formation, anchorage independent growth in semi-solid agar and autocrine growth factor production; full malignancy, including metastasis when the cells are injected into a suitable host, supporting the biological relevance of in vitro transformation to in vivo carcinogenicity. The Bhas 42 cell line was developed from BALB/c 3T3 cells through transfection with a Harvey rat sarcoma viral mutated oncogene homolog (v-Ha-ras). Since Ha-ras is strongly related to multi-step carcinogenesis, Bhas 42 cells are more predisposed to transformation than the original cells BALB/c 3T3. The assay was first developed by Ohmori et al. (2004) to identify tumour promoters. Subsequently, Asada et al. (2005) modified the Bhas 42 CTA protocol such that it was capable of detecting tumour initiating activity, as well as tumour promoting activity of chemicals. The current protocols consist of two assay components, the initiation assay and the promotion assay to detect the tumour-initiating and tumour-promoting activity of chemicals, respectively. Two variants of the protocol have been validated, a 6-well method and a 96-well method.","stepStage":"Regulatory acceptance/Standards > Drafting of new regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Drafting of new regulatory standard/guideline","topic":"Carcinogenicity","yearReceived":"2012","generalComments":"The validation of this assay was coordinated by the Japanese Center for the Validation of Alternative Methods (JaCVAM), while the peer review was conducted by ESAC.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=156","lastUpdate":"Monday, August 10, 2026 - 09:32","lastUpdateDate":"2026-08-10","stage":"Regulatory assessment","status":"Adopted","code":"REG_DRAFT","applicationDomain":"Mixed/general toxicology","endpoint":"Carcinogenicity","methodology":"In vitro","specificMethodologies":"HTS; Cell transformation assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM2020-01","shortName":"RS Comet assay","title":"3D Reconstructed Human Skin Comet assay","organisation":"EURL ECVAM - European Union","description":"The RS Comet Assay is an in vitro genotoxicity assay, presented as an adaptation of the known alkaline comet assay and designed in a three-dimensional reconstructed human skin (RHS) model. The method uses specifically the Phenion® Full-Thickness Skin Model which is composed of two tissues from primary and p53 competent cells of human origin, primary keratinocytes and fibroblasts. As such, the method is aimed to predict the potential of substances that are primarily associated with dermal exposure to cause DNA damage.","stepStage":"Regulatory acceptance/Standards > Drafting of new regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Drafting of new regulatory standard/guideline","topic":"Genotoxicity/Mutagenicity","yearReceived":"2020","generalComments":"Under evaluation","protocolSop":"","lastUpdate":"Wednesday, August 5, 2026 - 12:49","lastUpdateDate":"2026-08-05","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_DRAFT","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2020-04","shortName":"RSMN","title":"3D Reconstructed Human Skin Micronucleus assay (RSMN)","organisation":"EURL ECVAM - European Union","description":"The RS MN Assay is an in vitro genotoxicity assay, which transfers the known micronucleus test in a three-dimensional reconstructed human skin (3D RHS) model. The assay addresses the potential of test items to cause genotoxicity in the form of chromosomal damage (clastogenicity and aneugenicity). The method uses the EpiDerm™ Skin Model (MatTek, Ashland, USA) which is cultured from normal human epidermal keratinocytes derived from neo-natal foreskin tissue on specifically prepared tissue culture inserts. As such, the method is aimed to predict the potential of substances that are primarily associated with dermal exposure to cause DNA damage.","stepStage":"Regulatory acceptance/Standards > Drafting of new regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Drafting of new regulatory standard/guideline","topic":"Genotoxicity/Mutagenicity","yearReceived":"2020","generalComments":"Under evaluation","protocolSop":"","lastUpdate":"Wednesday, August 5, 2026 - 12:48","lastUpdateDate":"2026-08-05","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_DRAFT","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Micronucleus/genotoxicity assay; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2009-14","shortName":"HepaRG™","title":"Cytochrome P450 (CYP) enzyme induction in vitro method using cryopreserved differentiated human HepaRG™ cells","organisation":"EURL ECVAM - European Union","description":"The human cytochrome P450 (CYP) enzyme induction method assesses the potential of test chemicals to induce the activity of three CYP enzymes (CYP1A2, CYP2B6 and CYP3A sub-family) in cryopreserved differentiated human HepaRG™ cells. At the molecular level, CYP enzyme induction is a process controlled by a set of nuclear receptors associated with downstream signal transduction pathways. The human HepaRG™ cell model is a suitable candidate human hepatic metabolic competent test system. Experimentally, at the end of cell exposure to the test chemical, a cocktail of three specific CYP enzymatic substrate probes is applied to the cells and CYP enzyme induction is assessed through the measurement of of the specific metabolites formation by CYP1A2, 2B6 and 3A sub-family by analytical liquid chromatography/mass spectrometry (LC/MS) technique. The CYP enzyme induction in vitro methods (see also TM2009-13) are reliable and relevant methods for the generation of human metabolism data in animal-free testing strategies assessing adverse health effects of xenobiotics.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Toxicokinetics","yearReceived":"2009","generalComments":"","protocolSop":"Protocol for the CYP induction test method, OECD TG 445A","lastUpdate":"Thursday, July 2, 2026 - 15:50","lastUpdateDate":"2026-07-02","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Toxicokinetics","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM2022-03","shortName":"α-Sens®","title":"In Vitro Skin Sensitisation: The FBS free ARE-Nrf2 Luciferase α-Sens® Test Method","organisation":"JaCVAM - Japan","description":"The α-Sens® test method was developed to achieve a serum-free and simple operation procedure with high accuracy for the prediction of skin sensitizers. The α-Sens® employs a dual luciferase assay system to detect both antioxidant response element (ARE)-mediated transcriptional activity and cell viability to evaluate the KE-2 response, the keratinocyte activation of the AOP in the skin sensitization process. The α-Sens® cell line was originally developed as “α-Sens (without ®)”, the multi-clone cell system of PHK 16-0b cell line (immortalized human keratinocyte by HPV16 virus genome) stably transfected with two reporter constructs, Antioxidant response element (ARE) inducible Firefly luciferase gene for ARE response and Thymidine Kinase (TK) promoter-driven Renilla luciferase gene for cell viability measurement(Maeda et al., 2020). Therefore, the α-Sens can measure ARE-mediated activity and cell viability simultaneously with the same exposure sample. α-Sens was further improved by modifying the reporter gene construct and was established as a single clone cell system, “α-Sens® (with ®)","stepStage":"Regulatory acceptance/Standards > Revision of existing regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Revision of existing regulatory standard/guideline","topic":"Skin sensitisation","yearReceived":"2022","generalComments":"","protocolSop":"Protocol for α-Sens®","lastUpdate":"Friday, June 19, 2026 - 07:36","lastUpdateDate":"2026-06-19","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_OTHERSTAGE","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Reporter gene assay; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"External status check: α-Sens® was incorporated into the OECD TG 442D revision published 2 July 2026. The current TSAR snapshot may still reflect the preceding guideline-revision stage; update through the source-refresh workflow rather than manual expert override."},{"id":"TM2026-01","shortName":"LS Bioassay","title":"Lung Surfactant Bioassay","organisation":"EURL ECVAM - European Union","description":"The Lung Surfactant (LS) Bioassay is a cell-free method designed to assess acute lung toxicity shortly after inhalation, focusing on immediate alveolar effects. It evaluates LS function, which is crucial for healthy lungs, by monitoring surface tension and rheological changes in a 'breathing' drop of pig-derived LS exposed to test compounds. Increased surface tension, as measured with a Constrained Drop Surfactometer, and altered surface rheology, as calculated with a mathematical model, are considered inhibitory to LS function, potentially leading to alveolar collapse and breathing difficulties. Inhibition of LS function is identified as the Molecular Initiating Event in Adverse Outcome Pathway 302, predicting acute lung effects.According to the test submitter, the LS Bioassay is intended for non-regulatory prioritisation and chemical screening in research and development. While it assesses one of many inhalation effects, it might complement other lung-relevant in vitro methods and potentially replace acute inhalation toxicity tests following OECD Test Guidelines (TGs) that rely on systemic effects. Immediate lung effects can be noted in these TG studies by observing respiration changes. Coupling this method with OECD TGs can offer insights into the mechanism of toxicity of test compounds.","stepStage":"Submission > Assessment of presubmission","workflowStep":"Submission","workflowStage":"Assessment of presubmission","topic":"Acute toxicity, Human Health Effects","yearReceived":"2026","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, May 19, 2026 - 14:45","lastUpdateDate":"2026-05-19","stage":"Test Submission","status":"Ongoing","code":"SUB_ASSESS","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity; Human health — unspecified","methodology":"In chemico; In silico; Mixed","specificMethodologies":"","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The current specific-methodology vocabulary has no suitable label for constrained-drop surfactometry/biophysical surface-tension testing. AI/ML was rejected because the mathematical rheology model is not described as an AI or machine-learning method."},{"id":"TM2025-02","shortName":"InFiniteLungDT","title":"Quantitative prediction of inflammation from acute to chronic condition associated with inhalation and delivered ahead of time by lung animal-free in-vitro-learned digital twin (InFiniteLungDT)","organisation":"EURL ECVAM - European Union","description":"InFiniteLungDT is a quantitative prediction tool for inflammation transitioning from acute to chronic conditions associated with inhalation. It is an animal-free, in-vitro-learned digital twin designed to predict long-term, time-evolved, dose-dependent inflammation triggered by inhaled poorly-water-soluble substances. InFiniteLungDT works by monitoring subcellular dynamics in vitro using a lung epithelium cellular cluster. Live-cell microscopy captures time-lapse images, which are then quantified into 17 time-dependent observables. A patented algorithm translates these into interaction couplings, defining the material's Mode-of-Action (MoA). This MoA is then used for in silico time-propagation to predict dose-dependent endpoints (neutrophil influx) and LOAELs for up to two years, extending beyond the in vitro observation timescale. Two cell lines are used, the murine epithelial lung tissue cell line (LA-4) and the murine alveolar lung macrophages (MH-S).The intended purpose of the proposed method is to offer a resource-efficient alternative to animal testing, for regulatory applications (e.g. OECD TGs 403, 412, 413, and 452), delivering LOAELs for acute, sub-acute, sub-chronic, and chronic exposure scenarios. Additionally, it might support material developers in sectors such as advanced materials, nano and micromaterials, construction materials, and more, by facilitating early-phase pre-screening. The method is high-throughput compatible and can be scaled up for use by Contract Research Organisations (CROs).","stepStage":"Submission > Assessment of presubmission","workflowStep":"Submission","workflowStage":"Assessment of presubmission","topic":"Human Health Effects","yearReceived":"2025","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, May 19, 2026 - 07:59","lastUpdateDate":"2026-05-19","stage":"Test Submission","status":"Discontinued","code":"SUB_ASSESS","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity; Repeated dose toxicity; Chronic toxicity","methodology":"In vitro; In silico; Mixed","specificMethodologies":"HTS; High-content imaging","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Literature note: the full Urbančič et al. (2026) InFiniteLungDT pre-validation paper (bioRxiv DOI 10.64898/2026.05.12.723437) is not yet available locally; only a bibliographic reference record is stored in 02_Validation. Literature completeness therefore remains Partial until the full paper and any core supplementary material are added."},{"id":"TM2019-06","shortName":"TYRO-IOD","title":"Thyroid method 2c: Tyrosine iodination using liquid chromatography","organisation":"EURL ECVAM - European Union","description":"This method provides information on the Thyroid Peroxidase (TPO)-mediated iodination of tyrosine. The conversion from L-tyrosine to Iodotyrosine by TPO that is present in prepared extracts from FTC-238 cells transfected with human recombinant TPO, can be measured with LC-MS/MS. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Ongoing","workflowStep":"Validation","workflowStage":"Ongoing","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, April 7, 2026 - 10:06","lastUpdateDate":"2026-04-07","stage":"Validation","status":"Ongoing","code":"VAL_ONGO","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"The positive reproducibility/transferability signal refers specifically to the unresolved inter-laboratory transferability requirement; it should not be interpreted as evidence of poor within-laboratory reproducibility."},{"id":"TM2017-02","shortName":"TR MARCoNI","title":"Thyroid receptor microarray assay for real-time Nuclear Receptor-coregulator interaction","organisation":"EURL ECVAM - European Union","description":"Thyroid hormone signalling plays a key role in many physiological processes, including brain development and metabolism. The thyroid hormone elicits its action via the two types of thyroid hormone receptor (TR), TRα and TRβ. This method characterises TRα-Ligand Binding Domain (LBD) interaction with a range of coregulators, by assessing binding affinity of a defined set of immobilised nuclear receptor coactivator and corepressor peptides. The binding affinity is assessed via interaction with the LXXLL and LXXXIXXXL motifs for coactivators and corepressors respectively. The binding affinity is enhanced by ligand induced activation of the receptor, while ligand-independent binding reduces the binding affinity. The amount of ligand-modulated interaction of coregulators with TRα-LBD is assessed via image analysis, by adding fluorescent antibodies against TRα-LBD. The obtained binding profiles can be used to identify compounds that can activate TRα, thereby differentiating between agonistic and antagonistic action.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2017","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 13:20","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In chemico","specificMethodologies":"Binding/interaction assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Expert methodology correction: TR MARCoNI is coded as In chemico because it is a non-cellular recombinant receptor–coregulator peptide binding assay. 'Microarray' does not indicate omics here, and fluorescent image analysis/antibody detection are readout components rather than high-content imaging or a primary immunoassay."},{"id":"TM2016-01","shortName":"EDITOX","title":"Predictive testing for adverse psychiatric side effects","organisation":"EURL ECVAM - European Union","description":"The EDITOX test method is an in vitro cell assay designed to predict the risk of depression and/or suicidal adverse effects of a given drug in a patient. This test method quantitatively analyses variations of the relative proportion of the 32 mRNA editing isoforms of the serotonin receptor (5-HT2cR) (biomarkers) using a next generation sequencing (NGS) approach in SH-SY5Y cell line (human neuroblastoma). It is confirmed in the literature that anomalies of serotonin biology in brain appear to be a characteristic trait underlying depression and/or suicidal behavior (Dracheva et al., 2008). By analysing postmortem brain tissue of suicide victims, Alcediag and others have observed distinct epigenetic alterations of the RNA editing profile of the 5-HT2cR pre-mRNA, known to greatly impair its pharmacological properties (Weissmann et al. 2016; Dracheva et al., 2008; Burns et al. 1997), including significant decrease in its response to serotonin. Apparently, similar RNA editing profile of the 5-HT2cR is reproduced by an exposure to human IFNa (positive control) using SH-SY5Y cell line. IFNa is known to induce, in some patients treated for chronic type C hepatitis, full blown depression and suicidal behaviour (Cavarec et al. 2013). Based on this observation, the Submitter has developed a proprietary algorithm to assess whether the editing profile of tested drugs is close to the one induced by human IFNa, allowing categorisation of tested compounds into \"hIFNa-like\" vs \"non-hIFNa-like\" profiles. Furthermore, EDITOX test method is proposed to be used for classification of drugs into the following categories of “High risk”, “Low risk” or “Moderate risk” to induce adverse side effects, such as depression and/or suicide in pre-clinical drug development phase, and also in regulatory toxicological safety assessment.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Neurotoxicity, Human health","yearReceived":"2016","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 13:12","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical; Industrial chemicals","endpoint":"Neurotoxicity","methodology":"In vitro; In silico; Mixed","specificMethodologies":"Omics","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Outside-TSAR progression verified: after the TSAR submission was stopped, EDITOX continued in scientific and industrial development, including use of EDITOX assay data within the EU/IMI NeuroDeRisk programme and continued preclinical commercial application. This supports case_study_method = 1. No evidence of formal OECD/EMA/FDA regulatory adoption of EDITOX was identified. AI/ML was removed from the detailed methodology because a proprietary algorithm is described, but no explicit machine-learning/AI method was identified."},{"id":"TM2016-03","shortName":"ToxTracker","title":"ToxTracker Assay","organisation":"EURL ECVAM - European Union","description":"ToxTracker is an in vitro genotoxicity assay that also includes a number of non-genotoxic end points that have been associated with increased cancer hazard. ToxTracker detects induction of DNA damage, oxidative stress and protein unfolding, thereby providing insight into the mechanisms of (geno)toxicity, allowing accurate genotoxicity assessment and reducing the frequency of misleading positive in vitro test results that would trigger in vivo follow up testing.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Genotoxicity/Mutagenicity","yearReceived":"2016","generalComments":"Invitation to send full test submission","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 12:56","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Reporter gene assay; Cytotoxicity/cell viability assay; Immunoassay/flow cytometry; Biomarker/DNA damage assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Missing","verificationNote":"Outside-TSAR progression verified: ToxTracker continued through a parallel OECD route after the TSAR submission stopped, progressed through international multi-laboratory validation and independent peer review, and was adopted/published as OECD TG 446A on 2 July 2026. This supports case_study_method = 1 and External_evidence_step_stage = REG_ADOPT. TSAR source-copy lifecycle fields remain unchanged."},{"id":"TM2019-18","shortName":"PMOD-hNPC","title":"Thyroid method 8b: Proliferation, migration and oligodendrocyte maturation (including myelin formation) in mixed neuronal/glial culture (neurospheres) derived from human induced Pluripotent Stem Cells (hiPSC)","organisation":"EURL ECVAM - European Union","description":"Thyroid hormone disruption can interfere with proliferation, migration and differentiation of oligodendrocyte which may lead to neurodevelopmental impairments. The method encompasses evaluation of these biological processes using mixed neuronal/glial culture derived from human induced Pluripotent Stem Cells (hiPSC) cultured as free-floating neurospheres. Cell viability, proliferation, migration and differentiation measured by expression of myelin specific proteins are assessed following a 1-2-week treatment with test items. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 08:52","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Immunoassay/flow cytometry","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Mechanistic interpretation: PMOD-hNPC is a downstream human neurodevelopmental assay rather than a direct thyroid-hormone assay. It measures oligodendrocyte maturation/myelin-related outcomes and associated developmental processes that are sensitive to thyroid-hormone signalling, but an effect on myelination is not thyroid-specific and should be integrated with upstream thyroid-mechanistic evidence. Outside-TSAR progression was verified through later EURL ECVAM/JRC validation-oriented work with commercial hiPSC-derived BrainSpheres. This supports case_study_method = 1 and External_evidence_step_stage = VAL_ONGO; TSAR source-copy lifecycle fields remain unchanged."},{"id":"TM2019-16","shortName":"ZETA","title":"Thyroid method 7a: Measurement of intrafollicular thyroxine (T4) using zebrafish eleutheroembryos","organisation":"EURL ECVAM - European Union","description":"The Zebrafish Eleutheroembryo Thyroid Assay (ZETA) is used to detect direct thyroid gland function disruptors in the thyroid of 120 hours post- fertilisation (hpf) zebrafish embryos after their exposure to test items for 66 hours. The intrafollicular T4-content (IT4C) is determined by immunofluorescence signal. IT4C is a physiologically relevant integrative endpoint, as any potential disrupting mechanism of the thyroid gland function would result in increase or decrease of T4 production. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation, Peer-review > Finalised, Validation, Peer-review > Finalised","workflowStep":"Validation, Peer-review","workflowStage":"Finalised, Validation, Peer-review > Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 08:54","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Environmental","endpoint":"Endocrine disruption","methodology":"In vivo","specificMethodologies":"Immunoassay/flow cytometry; Embryo/developmental model","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: ZETA is an in vivo assay because it exposes an intact living zebrafish developmental stage (eleutheroembryos), even though this life stage may fall outside protected-animal legislation. The assay measures intrafollicular T4 by antibody-based immunofluorescence and therefore provides an integrated thyroid-gland functional endpoint rather than identifying one specific molecular mechanism. Conventional fluorescence microscopy is not coded as high-content imaging. Authoritative external evidence supports External_evidence_step_stage = VAL_PEER_FINAL; no later stage for the exact ZETA method was identified."},{"id":"TM2019-03","shortName":"TSH-CHOK1","title":"Thyroid method 1b: Thyrotropin-stimulating hormone (TSH) receptor activation based on cAMP measurement","organisation":"EURL ECVAM - European Union","description":"This method measures the production of cAMP after activation of the Thyroid Stimulating Hormone Receptor (TSHR). The production of intracellular adenosine 3’,5’ cyclic monophosphate (cAMP) is important for thyroid hormone physiology. cAMP is a critical component of a signal transduction pathway linking TSHR and its ligand TSH to the activation of adenylate cyclase and therefore cAMP production. The method measures the intracellular cAMP concentration in Chinese hamster ovary cells (CHO-K1) transfected with the gene of the human TSHR, using an Enzyme Linked Immuno Sorbent Assay. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation, Peer-review > Finalised, Validation, Peer-review > Finalised","workflowStep":"Validation, Peer-review","workflowStage":"Finalised, Validation, Peer-review > Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 08:56","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: TSH-CHOK1 is an in vitro functional TSH-receptor signalling assay using CHO-K1 cells expressing human TSHR. The primary endpoint is cAMP measured by an immunoassay/ELISA-type readout, with cell viability measurements used to distinguish receptor-signalling effects from general cytotoxicity. The assay therefore measures a specific upstream thyroid-signalling event rather than thyroid-hormone production itself. Authoritative external evidence supports External_evidence_step_stage = VAL_PEER_FINAL; no later lifecycle stage for the exact assay was identified."},{"id":"TM2019-10","shortName":"DIO1-SKR","title":"Thyroid method 4a: Deiodinase 1 activity based on Sandell-Kolthoff reaction","organisation":"EURL ECVAM - European Union","description":"This method assesses the inhibition of thyroid hormones deiodination, the major pathway regulating thyroid hormones bioavailability in mammalian tissues. This method measures the activity of deiodinase enzyme D1 in human liver microsomes by measurement of free iodine with a spectrophotometric absorbance readout following the Sandell-Kolthoff reaction, during which the yellow cerium(IV) is reduced to the colourless cerium (III). This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:03","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Ongoing","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"HTS; Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"Core methodology retained as In vitro to align with conventional toxicology terminology for the human-liver-microsome DIO1 assay. The test system is donor-derived human liver microsomal material, but the literature consistently describes the method as an in vitro microsomal assay. Detailed methodology corrected to HTS; Analytical chemistry readout; Enzyme/biochemical activity assay. Barrier/permeability and phototoxicity/photoreactivity labels were removed. External progression is supported beyond the TSAR VAL_FINAL snapshot through PEPPER transfer validation and formal OECD Test Guidelines Programme Project 4.179, supporting case_study_method = 1 and External_evidence_step_stage = REG_DRAFT."},{"id":"TM2019-11","shortName":"GLUC-LCMS","title":"Thyroid method 4b: Inhibition of thyroid hormones (THs) glucuronidation using liquid chromatography/mass spectrometry (LC/MS)","organisation":"EURL ECVAM - European Union","description":"This method assesses the potential of test items to inhibit the metabolism and excretion of thyroid hormones. Glucuronidation is one of the main pathways in the metabolism of thyroid hormones (T3 and T4). The method consists in the incubation of either T4 or T3 with human liver microsomes that contain UDP-glucuronosyltransferases (UGT), the enzyme involved in the glucuronidation. Following separation and purification the mixture is analysed by liquid chromatography/mass spectrometry (LC/MS). Acyl- and Phenolic- Glucuronides are separated and peaks identities confirmed. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:04","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: GLUC-LCMS is retained as In vitro for consistency with conventional toxicology terminology and with DIO1-SKR. It uses pooled human liver microsomes containing UGT enzymes and quantifies T3/T4 glucuronide formation by LC-MS/MS. The assay measures inhibition of thyroid-hormone glucuronidation, but this direction is not necessarily the predominant adverse in-vivo perturbation, because increased glucuronidation can drive increased thyroid-hormone clearance. No evidence of progression beyond the completed validation/peer-assessment stage was identified, so case_study_method = 0 and External_evidence_step_stage = VAL_FINAL."},{"id":"TM2019-19","shortName":"VAAN-hadum","title":"Thyroid method 8c: In vitro human adipose stromal cell—human umbilical vein endothelial cell (hASC-HUVEC) vasculogenesis/angiogenesis method","organisation":"EURL ECVAM - European Union","description":"Thyroid hormone disruption can interfere with vasculogenesis and angiogenesis and can be assessed using human primary adipose stromal cells and human primary umbilical vein endothelial cells coculture test without any artificial matrixes. In the method the effect of test item on the formation of vasculature is measured six days after the exposure by quantifying the formed tubules using image analysis. Cell viability test (WST-1) is used to measure general cytotoxicity to clarify if the inhibitory mechanism is related to cytotoxicity. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"","workflowStep":"","workflowStage":"","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:05","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"UNKNOWN_UNKNOWN","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"High-content imaging; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":"Expert interpretation: VAAN-hadum is a downstream human in vitro vasculogenesis/angiogenesis assay. Reduced or increased vascular-network formation is not thyroid-specific; the planned Part 2 study was intended to test that mechanistic relationship but was never performed. Part 1 did not document a reproducibility or performance failure; the thyroid-validation route stopped because programme capacity/human-resource constraints prevented continuation. Outside-TSAR development of the same hASC-HUVEC VAM platform in a different application domain (non-genotoxic carcinogenicity) supports case_study_method = 1, but this does not constitute formal lifecycle progression of the exact thyroid assay. Therefore External_evidence_step_stage = VAL_STOP, while the raw TSAR NEW_STEP_STAGE remains unchanged."},{"id":"TM2019-17","shortName":"T-SCREEN","title":"Thyroid method 8a: Measurement of proliferation of rat pituitary-derived cell line GH3","organisation":"EURL ECVAM - European Union","description":"This method is based on thyroid hormone (TH) dependent cell proliferation of a rat pituitary tumour cell line (GH3) in serum-free medium. It can be used to study interference of test items with TH at the cellular level, thus bridging the gap between limitations of assays using either isolated molecules (enzymes, transport proteins) or complex in vivo experiments with all the complex feedback mechanisms present. GH3 cell growth, which is measured with the colorimetric AlamarBlue™ assay is increased in the presence of TH agonists, and decreased in the presence of TH antagonists. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:06","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay; Binding/interaction assay; Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-15","shortName":"TRβ-CALUX","title":"Thyroid method 6b: CALUX human thyroid hormone receptor beta (TRβ) reporter gene transactivation measuring agonist and antagonist activities","organisation":"EURL ECVAM - European Union","description":"This method assesses the activation of thyroid hormone receptor beta (TRβ). It is making use of proprietary TRβ CALUX® cells which originated from human osteoblastic osteosarcoma U2OS line. These cells express a functioning human thyroid (TRβ) receptor coupled with a luciferase reporter gene. Test items with both an agonist or antagonist effect on TR activity can be detected and an increase or decrease of thyroid hormone signalling, results in corresponding changes in the expression of luciferase activity in TRβ CALUX® cells that can be measured with a luminometer. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Friday, June 5, 2026 - 11:18","lastUpdateDate":"2026-06-05","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-14","shortName":"TRαTRβ-REP","title":"Thyroid method 6a: Human thyroid hormone receptor alpha (TRα) and Human thyroid hormone receptor beta (TRβ) reporter gene transactivation measuring agonist activities","organisation":"EURL ECVAM - European Union","description":"This method assesses the activation of thyroid hormone receptor alpha (TRα) and beta (TRβ). It is making use of proprietary human HEK293 cells engineered to provide constitutive, high-level expression of the human TRα and TRβ coupled with a highly responsive luciferase reporter gene (commercially available kit from INDIGO Biosciences). Quantification of changes in luciferase expression in the treated vs. untreated reporter cells by detection of luminescence provides a sensitive measure of changes in TR activation without collateral induction/suppression of genes that are otherwise regulated by these transcription factors. This method allows to measure agonist TR functional activity. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:08","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-13","shortName":"MCT8-TR","title":"Thyroid method 5a: Inhibition of monocarboxylate transporter 8 (MCT8) based on Sandell-Kolthoff reaction","organisation":"EURL ECVAM - European Union","description":"This method measures the active transport of thyroid hormone T3 across the plasma membrane by monocarboxylate transporter 8 (MCT8). T3 uptake, by Madin Darby Canine Kidney (MDCK) cells stably transfected with human MCT8, is measured with a specrophotometric absorbance readout following the Sandell-Kolthoff (SK) reaction, during which the yellow cerium(IV) is reduced to the colourless cerium (III). This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:09","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay; Cytotoxicity/cell viability assay; Analytical chemistry readout; Enzyme/biochemical activity assay; Barrier/permeability/transport assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-12","shortName":"THSUL-LC","title":"Thyroid method 4c: Inhibition of THs sulfation using liquid chromatography","organisation":"EURL ECVAM - European Union","description":"This method assesses the potential of test items to inhibit the metabolism and excretion of thyroid hormones (THs,T3 and T4). Sulfation appears to be a primary step leading to the irreversible inactivation of TH and it is carried out by sulfotransferases (SULT); it increases the water solubility of TH, facilitating the excretion of sulfated TH via bile and urine. In humans, as sulfated TH can be hydrolysed to their precursor by the sulfatases present in tissues and gut microbiota, they are important as a reservoir for biological active iodothyronines. This assay measures the inhibition of THs by liquid chromatography/mass spectrometry (LC/MS). The potential inhibition of the compounds towards sulfation of T3 and T4 is determined by measuring and comparing the thyroid hormones sulfate conjugates formation, after incubation with and without the test chemicals. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:09","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-09","shortName":"T4-FITC","title":"Thyroid method 3b: Thyroxine-binding prealbumin (TTR) binding using fluorescence displacement (T4-FITC)","organisation":"EURL ECVAM - European Union","description":"This method investigates interference of test items with binding of thyroid hormones to human serum transport protein 'thyroxine-binding prealbumin (TTR)'. The principle of the method is that the addition of TTR-binding compounds to a mixture of TTR and a fluorescent conjugate FITC-T4 causes a decrease in fluorescence, because the TTR-binding compounds compete FITC-T4 out of the TTR binding-pocket and consequently lead to a decrease in the ratio of bound to unbound FITC-T4. The FITC-T4 conjugate exhibits higher fluorescence intensity when bound to TTR than in the unbound condition, probably due to the fact that the iodine atoms of the T4 present in the TTR binding pocket can no longer contribute to the intramolecular fluorescence quenching of the FITC-T4 conjugate. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:10","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Ongoing","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Binding/interaction assay; Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-08","shortName":"ANSA-FD","title":"Thyroid method 3a: Thyroxine-binding prealbumin (TTR) / thyroxine-binding globulin (TBG) binding using fluorescence displacement (ANSA)","organisation":"EURL ECVAM - European Union","description":"This method investigates interference of test items with binding of thyroid hormones to human serum transport proteins 'thyroxine-binding prealbumin' (TTR) and 'thyroxine-binding globulin' (TBG). The binding of 8-anilino-1-naphtalenesulfonic acid (ANSA) to TTR or TBG produces fluorophore complexes with intrinsic fluorescence signal. In the presence of competitive ligands, displacement of ANSA occurs and the fluorescence signal detected decreases. Binding/displacement capacity of endocrine/thyroid disrupting chemicals can be assessed and compared to that of T3 and/or T4. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:12","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Binding/interaction assay; Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-07","shortName":"NIS-SKR","title":"Thyroid method 2d: Activation of the sodium iodide symporter (NIS) based on Sandell-Kolthoff reaction","organisation":"EURL ECVAM - European Union","description":"This method measures the active transport of extracellular iodide across the cellular membrane of cells expressing a functional sodium/iodide (Na+/I-) symporter (NIS), an intrinsic membrane glycoprotein that actively transports iodide from blood into thyroid follicular cells during the initial step of TH synthesis. This method is designed to identify test items that inhibit NIS-mediated iodide uptake by directly competing with iodide for intracellular transport, or indirectly, through an inhibition of Na+/K+ ATPase that disrupts maintenance of the critical cross-membrane sodium gradient required for NIS functionality. Reduction of intracellular iodide is measured as optical density with a spectrophotometric readout following the Sandell-Kolthoff (SK) reaction. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:13","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay; Barrier/permeability/transport assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-04","shortName":"AUR-TPO","title":"Thyroid method 2a: Thyroperoxidase (TPO) inhibition based on oxidation of Amplex UltraRed","organisation":"EURL ECVAM - European Union","description":"This method evaluates the activity of the thyroperoxidase (TPO), a key enzyme for the synthesis of thyroid hormones. The method allows to identify TPO-inhibiting test items by assessing the enzyme activity in prepared extracts from FTC-238 cells transfected with human recombinant TPO. TPO activity is measured through the oxidation of a commercially-available peroxidase substrate (Amplex UltraRed, AUR, ® LifeTech) and its conversion to a fluorescent product. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:13","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Finalised","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Enzyme/biochemical activity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-02","shortName":"TRH-CHOK1","title":"Thyroid method 1a: PATHHUNTER® BETA-ARRESTIN thyrotropin-releasing hormone (TRH) receptor activation (beta-galactosidase) measuring agonist and antagonist activities","organisation":"EURL ECVAM - European Union","description":"This method is a chemiluminescent in vitro method which measures the agonist and antagonist activities of test items by assessing the thyrotropin-releasing hormone receptor (TRHR) activation. The method employs the commercially available Chinese hamster ovary cells (CHO-K1) engineered to stably express the tagged proteins TRHR and β-Arrestin (PathHunter® CHO-K1 TRHR β-Arrestin Cell Line). Following chemical-TRHR binding, the ProLink™ tagged GPCR is activated inducing the recruitment of Enzyme Acceptor tagged β-Arrestin, forcing complementation of the two enzyme fragments. The resulting functional enzyme hydrolyses the substrate to generate a chemiluminescent signal. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods ’.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:14","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay; Enzyme/biochemical activity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2025-01","shortName":"GARDSkin DR","title":"GARDskin Dose-Response","organisation":"EURL ECVAM - European Union","description":"The GARDskin Dose Response (DR) method is a transcriptomics-based in vitro assay measuring with a NanoString nCounter instrumentation the transcriptional levels of a panel of genes called the GARDskin Prediction Signature (GPS). It is a variation of the established GARDskin assay (TSAR TM2011-09; OECD TG 442E) for skin sensitisation assessment. Consistently with the GARDskin, the GARDskin DR addresses the third key event of the skin sensitisation Adverse Outcome Pathway (activation of dendritic cells). It uses the very same cell system (a subclone of the MUTZ-3 cell line), protocols, and analysis pipeline, but instead of testing at a single concentration as in the traditional GARDskin, it measures gene expression across a range of concentrations. In addition, it provides an add-on to the established prediction model allowing to convert the data into a \"Predicted Potency Value\" which is proposed for discriminating between UN GHS subcategory 1A skin sensitisers from those not categorised as subcategory 1A i.e., subcategory 1B or no category.","stepStage":"Submission > Assessment of full submission","workflowStep":"Submission","workflowStage":"Assessment of full submission","topic":"Skin sensitisation","yearReceived":"2025","generalComments":"","protocolSop":"","lastUpdate":"Thursday, July 24, 2025 - 12:09","lastUpdateDate":"2025-07-24","stage":"Test Submission","status":"Ongoing","code":"SUB_ASSESS","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro; In silico; Mixed","specificMethodologies":"Omics; AI/ML","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2024-01","shortName":"BBB-oC","title":"Blood-brain barrier-on-a-chip (BBB-oC) for drug testing of brain-targeting delivery","organisation":"EURL ECVAM - European Union","description":"The Blood-brain barrier-on-a-chip (BBB-oC) is a 3D co-culture of brain microvascular endothelial cells, pericytes, astrocytes and/or neurons in a microfluidic interconnected three-chamber device. The BBB-oC is designed to evaluate the permeability of the BBB, by transendothelial electrical resistance (TEER) measurement through integrated microelectrodes and fluorescent measurements using tracers of different molecular weight. The method is proposed as an in vitro alternative for the evaluation of the performance of brain-targeting drugs.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Human health","yearReceived":"2024","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, June 3, 2025 - 13:10","lastUpdateDate":"2025-06-03","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Pharmaceutical","endpoint":"Human health — unspecified","methodology":"In vitro","specificMethodologies":"MPS; Microfluidic; Analytical chemistry readout; Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2016-02","shortName":"Bioelution","title":"Bioaccessibility testing (Bioelution) of metals, inorganic metals compounds and metals-containing materials: simulated gastric fluid","organisation":"EURL ECVAM - European Union","description":"The bioelution test measures the fraction of a substance that dissolves under surrogate physiological conditions (i.e. simulated gastric fluid) and is potentially available for absorption into systemic circulation (bioaccessible concentration). This test method is not a toxicity test. The test submitter proposed to use the method in a compartive manner (target and reference material) to generate relative bioaccessible metal ion data for the oral route of exposure, which they consider relevant to systemic effects of metal-containing materials. The relative results obtained could be used to make predictions of how the test material will behave compared to the reference material, based on relative metal ion release. This assumes that the dissolved metal ion is the cause of toxicity. The test method was then proposed to support read across and grouping under REACH for systemic endpoints and to assign CLP classifications. In the context of hazard classification, the test method has been proposed as a refinement to the current approach to alloy classification. Alloys are defined as special preparations under REACH in recognition of the fact that they do not behave as simple mixtures (EC, 2006). Thus, the rationale is that the gastric bioaccessible concentration of a metal in an alloy appears more informative and then relevant for predicting the toxicity than simply using the concentration of the metal ingredient. The systemic toxicity of most metals and metalloids is associated to a large degree with the release of soluble metal ions and their uptake by the body and/or interaction at their target organ sites (i.e., the bioavailability of the metal ions). The simple presence of a metal or inorganic ion in a substance does not necessarily impart to that substance the biological properties of the metal/inorganic ion; it is the bioavailability of the ion at the site of action in the organism that is the most important factor determining toxicity for metals and minerals.","stepStage":"Regulatory acceptance/Standards > Stopped","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Stopped","topic":"Bioaccessibility","yearReceived":"2016","generalComments":"","protocolSop":"Bioelution Protocol - Feb 2025","lastUpdate":"Thursday, April 16, 2026 - 09:12","lastUpdateDate":"2026-04-16","stage":"Regulatory assessment","status":"Rejected","code":"REG_STOP","applicationDomain":"Pharmaceutical; Industrial chemicals","endpoint":"Bioaccessibility","methodology":"In silico; In chemico; Mixed","specificMethodologies":"Read-across/WoE; Barrier/permeability/transport assay; Bioaccessibility/bioelution assay","review":"AI-reviewed","threeR":"Refinement","literature":"Complete","verificationNote":""},{"id":"TM2018-01","shortName":"EpiSensA","title":"Epidermal Sensitization Assay","organisation":"JaCVAM - Japan","description":"The EpiSensA is an in vitro method for measuring the expression of four marker genes (ATF3, encoding Activating transcription factor 3; GCLM, encoding Glutamate-cysteine ligase, modifier subunit; DNAJB4, encoding DnaJ (Hsp40) homolog, subfamily B, member4; IL-8, encoding Interleukin-8) of the reconstructed human epidermis (RhE) following controlled exposure of test chemicals. The two main important keratinocyte responses that occur in the skin sensitization adverse outcome pathway are Inflammatory response and Induction of cytoprotective gene pathways. The assay is based on the induction of the multiple marker genes related to these two keratinocyte responses.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2018","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/JACVAM/EpiSensA%20SOP%20v2.6.pdf, https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/JACVAM/EpiSensA_Datasheet_en.xlsx, https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/JACVAM/EpiSensA%20SOP%20v2.6.pdf, https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/JACVAM/EpiSensA_Datasheet_en.xlsx","lastUpdate":"Monday, March 9, 2026 - 11:10","lastUpdateDate":"2026-03-09","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro; In chemico; Mixed","specificMethodologies":"Organoid/3D tissue model; Immunoassay/flow cytometry; Chemical reactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2020-02","shortName":"22Rv1/MMTV_GR-KO","title":"Androgen Receptor Transactivation Assay for Detection of androgenic Agonist and Antagonist Activity of Chemicals using the stably transfected human 22Rv1/MMTV_GR-KO cell line","organisation":"OECD - International Organisation","description":"The 22Rv1/MMTV_GR-KO AR-mediated stably transfected transcriptional activation (TA) assay was established to screen chemicals for endocrine activity via interaction with the AR using a human prostate cancer cell line, 22Rv1, that endogenously expresses the AR (1, 2). This test method is specifically designed to detect human AR-mediated TA and inhibition by measuring luciferase activity as the endpoint. The information of chemical dependent interference with luminescence signals is limited in a GR-knockout 22Rv1/MMTV cell line.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Endocrine disruption","yearReceived":"2020","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 09:58","lastUpdateDate":"2026-04-02","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2016-09","shortName":"VM7Luc ER TA","title":"The The VM7Luc ER TA test method: An In Vitro Assay for Identifying Human Estrogen Receptor Agonist and Antagonist Activity of Chemicals","organisation":"ICCVAM/NICEATM - United States","description":"The VM7Luc ER TA test method (also known as the LUMI-CELL® test method) was developed by Xenobiotic Detection Systems, Inc., with support from NIEHS Small Business Innovation Research grant ES10533-03. The test method measures the extent to which a substance induces or inhibits transcriptional activity (TA) via ER-mediated pathways in recombinant VM7Luc4E2 cells. The VM7Luc4E2 cell line was derived from the MCF7 human breast cancer cell line that endogenously express both human ER forms, ERα and ERβ, and that have been stably transfected with the plasmid pGudLuc7.ERE. This plasmid contains four copies of a synthetic oligonucleotide containing the estrogen response element upstream of the mouse mammary tumor viral promoter and the firefly luciferase gene. VM7Luc4E2 cells emit measurable light in response to estrogen and estrogen-like substances. In 2016, NICEATM received new information regarding the LUMI-CELL® test. DNA testing has now shown that the original cell line used to develop the test was not the BG1 human ovarian carcinoma cell line. It was a variant of the MCF7 human breast cancer cell line. The cell line used in the test, originally referred to as BG1Luc4E2 (Rogers and Denison 2000), will now be designated as VM7Luc4E2 (\"V\" = variant; \"M7\" = MCF7 cells). Likewise, the test will now be generically referred to as the VM7Luc ER TA test. While this changes the origin of the cell line upon which the test is based, it does not affect published validation studies nor the use and application of this test for screening of estrogenic/anti-estrogenic chemicals.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2016","generalComments":"This test method was originally referred to as the BG1Luc ER TA method.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=455","lastUpdate":"Monday, December 16, 2024 - 11:30","lastUpdateDate":"2024-12-16","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":""},{"id":"TM2011-09","shortName":"GARD","title":"Genomic Allergen Rapid Detection test","organisation":"EURL ECVAM - European Union","description":"The Genomic Allergen Rapid Detection (GARD) is a transcriptomics-based in vitro assay proposed to assess the skin sensitisation potential/potency of chemicals. GARD addresses the third key event of the skin sensitisation Adverse Outcome Pathway (activation of dendritic cells), step 5 (biochemical pathways related to skin sensitisation) and step 6 (immune recognition of chemical allergens and maturation of dendritic cells (DCs)). The test method has two elements: the so-called GARDskin to assess skin sensitisation potential (first submission in October 2011) and GARDpotency to assess skin sensitisation potency (first submission in July 2018). The test method is based on the nCounter system and measures the expression level of a panel of genes in the human myeloid cell line MUTZ-3 exposed to chemicals. In GARDskin, the expression of a panel of 200 genes (the GARD Prediction Signature, GPS) is used as input to a prediction model based on a Support Vector Machine (SVM) trained with 38 chemicals. This model classifies chemicals as skin sensitising or non-sensitising. The GARDpotency can be considered as second-tier of a testing strategy, following GARDskin. Thus, in GARDpotency, the model sub-categorises sensitisers into GHS/CLP categories 1A (strong/extreme sensitisers) or 1B (weak/moderate sensitisers) based on the expression of a panel of 52 genes (the GARD Potency Prediction Signature, GPPS).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Sensitisation","yearReceived":"2011","generalComments":"Please note that the GARDskin Assay Protocol available in the link above is a revised version provided by the test method developer after completion of the ESAC peer review to address comments made by the ESAC.","protocolSop":"GARDskin Assay Protocol","lastUpdate":"Thursday, April 2, 2026 - 10:00","lastUpdateDate":"2026-04-02","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Sensitisation — unspecified","methodology":"In vitro; In silico; Integrated approach; Mixed","specificMethodologies":"Omics; AI/ML; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-11","shortName":"SENS-IS","title":"SENS-IS","organisation":"EURL ECVAM - European Union","description":"The SENS-IS assay is a patent-protected gene expression-based test method proposed to discriminate between skin sensitisers, non-sensitisers and skin irritants by analysing the expression in Reconstructed human Epidermis (RhE) of a panel of 65 genes grouped in one gene set for irritancy (IRR) and two (SENS-IS and ARE) for sensitisation. In addition, the test method allows the classification of sensitisers into potency categories on the basis of the concentration of chemical needed to induce a positive response. A test substance is classified as sensitiser on the basis of the number of overexpressed genes (compared to solvent control) measured by qRT-PCR in Episkin RhE tissues. The biomarkers have been selected starting with data mining, followed by treatment with either sensitisers or irritants in the LLNA model, further refined using qPCR analysis of suction blisters on human volunteers sensitised to Nickel or fragrance mix in a controlled clinical trial, and final selection based on testing data in Episkin RhE tissues. The test system used is the commercially available EpiskinTM, a 3D RhE obtained by culturing adult human keratinocytes on a collagen substrate to permit their terminal differentiation and the reconstruction of an epidermis with a functional stratum corneum. According to the test submitter, this model can take account of skin metabolism and skin penetration and should be widely applicable to testing of chemicals, including pre and pro-haptens, solids and liquids.","stepStage":"Peer-review > Stopped","workflowStep":"Peer-review","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2011","generalComments":"Under external validation","protocolSop":"","lastUpdate":"Thursday, May 5, 2022 - 11:59","lastUpdateDate":"2022-05-05","stage":"Validation","status":"Discontinued","code":"VAL_PEER_STOP","applicationDomain":"Cosmetics; Pharmaceutical; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Omics; Organoid/3D tissue model; Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2010-07","shortName":"AR-CALUX","title":"Transactivation assay for detection of androgenic activity of chemicals","organisation":"EURL ECVAM - European Union","description":"Androgen Receptor TransActivation assay (ARTA). This method makes use of the osteosarcoma celline U2-OS which has been transfected with the full cDNA for the human androgen receptor (pSG5-neo-hAR), and, a reporter gene for luciferase expression under control of a limited promoter and a triple tandem of upstream elements ARE (pGL3-3XAREtataLuc). This method provides information on the (anti-) androgenic activity of substances when the AR-CALUX cells are exposed, leading to luminescence. The measurements and the classification model allow to predict if substances have a positive or negative reponse for either the agonist or antagonist mode of the method. This method is intended for screening purposes.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2010","generalComments":"The AR-CALUX method was submitted by BioDetection Systems (The Netherlands) for a EURL ECVAM coordinated validation study. The experimental part was concluded by the end of 2018 and the report reviewed by ESAC in June 2019. The draft TG (TG458) was submitted to OECD mid June 2019, for commenting rounds to start at WNT. The TG458 was adopted (April 2020) and published(June 2020). This TG includes 3 validated ARTA methods: AR-EcoScreen from Japan, AR-CALUX from the Netherlands, 22Rv1/MMTV_GR-KO assay from Korea.","protocolSop":"https://publications.jrc.ec.europa.eu/repository/bitstream/JRC116993/JRC116993_02.pdf, https://publications.jrc.ec.europa.eu/repository/bitstream/JRC116993/JRC116993_02.pdf","lastUpdate":"Tuesday, September 2, 2025 - 14:02","lastUpdateDate":"2025-09-02","stage":"Regulatory assessment","status":"Adopted","code":"VAL_PEER_FINAL","applicationDomain":"Industrial chemicals","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay; AI/ML","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2022-01","shortName":"ProtReact","title":"ProtReact","organisation":"EURL ECVAM - European Union","description":"The ProtReact is an in chemico method that addresses the covalent binding of electrophilic chemicals with nucleophilic sites of amino acids in skin proteins (i.e., haptenation) which represents the molecular initiating event of the skin sensitisation Adverse Outcome Pathway. The test method measures reactivity of a test chemical by quantifying through fluorescence/absorbance, the depletion of lysine and cysteine peptides in 96 well-plates. It is proposed to contribute to the skin sensitisation hazard assessment of chemicals.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Skin sensitisation","yearReceived":"2022","generalComments":"","protocolSop":"","lastUpdate":"Monday, December 16, 2024 - 11:12","lastUpdateDate":"2024-12-16","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"In chemico","specificMethodologies":"Analytical chemistry readout; Binding/interaction assay; Chemical reactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2021-01","shortName":"LUCS-VALITOX","title":"LUCS (Light-up Cell System)-VALITOX","organisation":"EURL ECVAM - European Union","description":"The LUCS test method (light-up cell system) measures general or basal cytotoxicity in cells of human origin. The test method uses thiazole orange (TO) as fluorescent dye that passively enters the cells and binds to nucleic acids. In homeostatic cells, efflux transport proteins quickly remove the dye limiting their access to the nucleic acids and keeping the fluorescent levels inside the cells low. Changes in cell homeostasis result in the dye entering the cell massively and binding to the nucleic acids, increasing the fluorescence levels. There is production of ROS inside live cells by light induction and the fluorescence before and after applying light, both in healthy (untreated) and treated cells is measured. The change in fluorescence levels are higher in untreated cells compared to treated cells, which have lost homeostasis. The test method is proposed as: 1) a method to describe cytotoxicity, and 2) a method to inform acute oral toxicity, in particular for providing the starting dose for the in vivo acute oral toxicity test as described in OECD GD 129.","stepStage":"Submission > Assessment finalised","workflowStep":"Submission","workflowStage":"Assessment finalised","topic":"Acute toxicity","yearReceived":"2021","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 11:37","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay; Binding/interaction assay; Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1994-01","shortName":"3T3NRU Phototoxicity","title":"The 3T3 neutral red uptake (NRU) phototoxicity assay","organisation":"EURL ECVAM - European Union","description":"The 3T3 Neutral Red Uptake (NRU) assay is based on an immortalised mouse fibroblast cell line called Balb/c 3T3. The method is based on a comparison of the cytotoxicity of a chemical when tested in the presence or absence of exposure to a non-cytotoxic dose of simulated solar light (i.e. ultra-violet light). Cytotoxicity in this test is expressed as a concentration-dependent reduction of the uptake of the vital dye neutral red when measured 24 hours after treatment with the test chemical and irradiation. The test chemical together with the irradiation may alter the cell surface and in effect may result in a decreased uptake and binding of the neutral red dye. Differences in this uptake can be measured with a spectrophotometer, which allows the distinction and quantification between viable, damaged or dead cells.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin irritation","yearReceived":"1994","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=78","lastUpdate":"Thursday, April 16, 2026 - 09:30","lastUpdateDate":"2026-04-16","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Phototoxicity","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay; Barrier/permeability/transport assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM1997-02","shortName":"EpiDerm-PT","title":"Human 3-D Epidermis Model in Vitro Phototoxicity Test","organisation":"EURL ECVAM - European Union","description":"The test method is based on the commercially available EpiDerm™ model, a reconstructed human epidermal (RhE) model grown from human-derived epidermal keratinocytes, which are cultured to form a multilayered and highly differentiated model of the human epidermis. The SOP has been developed on the basis of the Skin2 test in 1997 and method validation conducted during 1997-1999. A follow-up study has been performed during 2002-2005 to access whether the method can also address the potency of the topically applied photo-toxins. The Phototoxicity of chemicals is assessed by the measurement cytotoxic response of irradiated and non-irradiated RhE model. The method can be used as stand-alone or in combination with OECD TG 432 and other assays depending on the outcomes and regulatory schemes. The test was accepted in 2015 into the ICH Guideline S10 Photosafety evaluation of pharmaceuticals.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Basal Cytotoxicity","yearReceived":"1997","generalComments":"","protocolSop":"http://cidportal.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/DBALM_docs/121_P_EpiDermTM%20Phototoxicity%20Assay.pdf","lastUpdate":"Thursday, April 2, 2026 - 12:34","lastUpdateDate":"2026-04-02","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Pharmaceutical","endpoint":"Basal cytotoxicity; Phototoxicity","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2003-03","shortName":"BCOP","title":"Bovine corneal opacity and permeability test method","organisation":"ICCVAM/NICEATM - United States","description":"The Bovine Corneal Opacity and Permeability test method (BCOP) is an in vitro test method that can be used to identify chemicals (substances or mixtures) as either 1) causing “serious eye damage” (category 1 of the Globally Harmonised System for the Classification and Labelling of chemicals (GHS)), or 2) not requiring classification for eye irritation or serious eye damage according to the GHS. BCOP is an organotypic model that provides short-term maintenance of normal physiological and biochemical function of the bovine cornea in an isolated system. Damage by the test substance is assessed by quantitative measurements of changes in corneal opacity and permeability with an opacitometer and an ultraviolet/visible (UV/VIS) spectrophotometer, respectively. Both measurements are used to calculate an In Vitro Irritancy Score, which is used to assign an in vitro irritancy classification for prediction of the in vivo ocular irritation potential of a test substance. Although not part of the adopted OECD test guideline, histopathology can be useful to discriminate borderline cases (i.e., substances that produce results that preclude assignment to a single category) or to identify ocular damage that does not produce opacity or permeability changes in the isolated cornea. Histopathology can also be used where the mode of action cannot be easily predicted, when delayed effects might be anticipated, or when a more complete characterization of damage is needed","stepStage":"Recommendation > Published","workflowStep":"Recommendation","workflowStage":"Published","topic":"Serious eye damage/Eye irritation","yearReceived":"2003","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:14","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REC_PUBL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"High-content imaging; Organoid/3D tissue model; Analytical chemistry readout; Barrier/permeability/transport assay; Ex vivo/tissue-based assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2003-02","shortName":"ICE","title":"Isolated Chicken Eye","organisation":"ICCVAM/NICEATM - United States","description":"The Isolated Chicken Eye test method (ICE) is an in vitro test method that can be used to identify chemicals (or substances or mixtures) as either 1) causing \"serious eye damage\" (Category 1 of the Globally Harmonized System for the Classification and Labelling of Chemicals (GHS)), or 2) not requiring classification for eye irritation or serious eye damage according to the GHS. ICE is an organotypic model that provides short-term maintenance of the chicken eye, a byproduct of processing plants. Damage caused by the test substance is assessed by quantitative determination of corneal swelling and qualitative assessment of opacity and fluroescein retention. Each measurement is either 1) converted into a quantitative score that is used to calculate an overall in vitro ocular irritation index or 2) assigned a qualitative categorization that is used to assign an in vitro ocular irritancy classification. Either outcome can then be used to predict the in vivo ocular irritation potential of a test substance.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Serious eye damage/Eye irritation","yearReceived":"2003","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:12","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Organoid/3D tissue model; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-15","shortName":"STE","title":"Short Time Exposure Test","organisation":"ICCVAM/NICEATM - United States","description":"The Short Time Exposure (STE) test is an in vitro test method that identifies the eye injury hazard potential of test substances applied to cultured corneal epithelial cells with cell viability used as the endpoint for quantitation of the extent of injury.","stepStage":"Submission > Assessment finalised","workflowStep":"Submission","workflowStage":"Assessment finalised","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:10","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"SUB_FINAL","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-16","shortName":"Antimicrobial Cleaning Product Testing Strategy","title":"Antimicrobial Cleaning Product Testing Strategy","organisation":"ICCVAM/NICEATM - United States","description":"Testing strategy uses the bovine corneal opacity and permeability (BCOP), Cytosensor microphysiometer (CM), and EpiOcular (EO) test methods to determine EPA hazard category and labeling requirements.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:08","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro; Integrated approach; Ex vivo; Mixed","specificMethodologies":"Organoid/3D tissue model; Barrier/permeability/transport assay; Ex vivo/tissue-based assay; Integrated testing strategy/battery; Metabolic activity sensor assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1998-05","shortName":"Murine Local Lymph Node Assay","title":"Murine Local Lymph Node Assay","organisation":"ICCVAM/NICEATM - United States","description":"Skin sensitizers induce a primary sensitization of lymphocytes in the auricular lymph nodes that drain the site of test chemical application. In the LLNA, lymphocyte proliferation is proportional to the dose of test chemical applied and is used as a measure of sensitization after weighing the lymph nodes, then extracting and labeling the cells with 3H-methyl thymidine and measuring disintegrations per minute (DPM).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Sensitisation","yearReceived":"1998","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:31","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Industrial chemicals","endpoint":"Sensitisation — unspecified","methodology":"In vivo","specificMethodologies":"None identified","review":"AI-reviewed","threeR":"Refinement","literature":"Complete","verificationNote":""},{"id":"TM2013-04","shortName":"Ros Assay","title":"Ros (Reactive Oxygen Species) Assay for Photoreactivity","organisation":"JaCVAM - Japan","description":"Phototoxicity is defined as a toxic response is elicited by topically or systemically administered photoreactive chemicals after the exposure of the body to environmental light. The ROS assay was designed for qualitative photoreactivity assessment of chemicals, the principle of which is monitoring of type I (an electron or hydrogen transfer, resulting in the formation of free radical species) and type II (an energy transfer from excited triplet photosensitizer to the oxygen) photochemical reactions in test chemicals exposed to simulated sunlight. In the ROS assay, SO generation is detected by spectrophotometric measurement of p-nitrosodimethylaniline (RNO) bleaching, followed by decreased absorbance of RNO at 440 nm.","stepStage":"Regulatory acceptance/Standards > Published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Published","topic":"Skin irritation, Skin sensitisation, Genotoxicity/Mutagenicity","yearReceived":"2013","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 18:17","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_PUBL","applicationDomain":"Cosmetics; Environmental","endpoint":"Skin irritation; Skin sensitisation; Genotoxicity; Photoreactivity","methodology":"In chemico","specificMethodologies":"Analytical chemistry readout; Phototoxicity/photoreactivity assay; Bioaccessibility/bioelution assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2016-10","shortName":"IL-8 Luciferase assay for skin sensitization","title":"IL-8 Luciferase assay for skin sensitization","organisation":"JaCVAM - Japan","description":"The IL-8 Luc assay measures changes in IL-8 expression, a cytokine associated with the activation of dendritic cells (key event 3) for evaluating skin sensitisation potential of chemicals. In the THP-1-derived IL-8 reporter cell line, IL-8 expression is measured as luciferase activity.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:22","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM2011-15","shortName":"Vitrigel-Eye Irritancy Test","title":"Vitrigel-Eye Irritancy Test","organisation":"JaCVAM - Japan","description":"The Vitrigel-Eye Irritancy Test (EIT) method is an in vitro test method that allows the identification of test chemicals not requiring classification and labelling for eye irritation or serious eye damage (GHS No Category) as defined by the UN GHS without further testing. This method assesses the eye irritation potential of a test chemical based on its ability to induce damage to the barrier function of the human corneal epithelium (hCE) models. In this test method, time-dependent changes in the Transepithelial Electrical Resistance (TEER) values are indicative of damage to the barrier function of the corneal epithelium following exposure to a test chemical.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2011","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:22","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Barrier/permeability/transport assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2012-07","shortName":"AR-Ecoscreen test","title":"Androgen Receptor TransActivation Assay using the stably transfected human AR-EcoScreen™ cell line","organisation":"JaCVAM - Japan","description":"The AR-EcoScreen™ method uses the AR-EcoScreenTM cell line to detect (anti)androgenic activity. This method exclusively addresses transactivation and inhibition of an androgen-regulated reporter gene by binding to the human AR, and therefore it should not be directly extrapolated to the complex in vivo situation of androgen regulation of cellular processes. This test method is specifically designed to detect human AR-mediated transactivation and inhibition by measuring luciferase activity as the endpoint. In addition, the assay is only likely to inform on the activity of the parent molecule bearing in mind the limited metabolising capacities of the in vitro cell systems.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Endocrine disruption","yearReceived":"2012","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 20:12","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM2008-17","shortName":"ER-STTA assay","title":"Stably Transfected Human Estrogen Receptor-α Transactivation Assay using the (h) ERα-HeLa-9903 cell line","organisation":"JaCVAM - Japan","description":"This transactivation (TA) assay uses the (h) ERα-HeLa-9903 cell line to detect estrogenic agonist activity mediated through human estrogen receptor alpha ((h) ERα). This test method is specifically designed to detect (h) ERα-mediated TA by measuring chemiluminescence as the endpoint.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Endocrine disruption","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:23","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM2016-12","shortName":"ADRA for skin sensitization","title":"In Chemico Skin Sensitisation: Amino acid Derivative Reactivity Assay","organisation":"JaCVAM - Japan","description":"The ADRA is proposed to address the molecular initiating event of the skin sensitisation AOP—namely, protein reactivity—by quantifying the reactivity of test chemicals towards model synthetic amino acid derivatives containing either lysine (NAL) or cysteine (NAC). The relative concentrations of NAC and NAL are measured by high-performance liquid chromatography (HPLC) with gradient elution and UV detection at 281 nm. Percent depletion values are then calculated for both NAC and NAL to discriminate between skin sensitisers and non-sensitisers.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:23","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin sensitisation","methodology":"In chemico","specificMethodologies":"Analytical chemistry readout; Chemical reactivity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":""},{"id":"TM2008-14","shortName":"LabCyte EPI-MODEL24 SIT","title":"LabCyte EPI-MODEL24 skin irritation test","organisation":"JaCVAM - Japan","description":"This method is based on the in vitro test system of reconstructed human epidermis (RhE), which closely mimics the biochemical and physiological properties of the upper parts of the human skin, i.e. the epidermis. The test chemical is applied topically to a three-dimensional RhE model, comprised of non-transformed human-derived epidermal keratinocytes, which have been cultured to form a multilayered, highly differentiated model of the human epidermis. Cell viability in RhE models is measured by enzymatic conversion of the vital dye MTT [3-(4,5-Dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide, Thiazolyl blue; CAS number 298-93-1], into a blue formazan salt that is quantitatively measured after extraction from tissues (31). Irritant chemicals are identified by their ability to decrease cell viability below defined threshold levels.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin irritation","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:24","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2017-03","shortName":"LabCyte EPI-MODEL24 SCT","title":"LabCyte EPI-MODEL24 skin corrosion test","organisation":"JaCVAM - Japan","description":"Skin corrosion refers to the production of irreversible damage to the skin manifested as visible necrosis through the epidermis and into the dermis, following the application of a test chemical. The test chemical is applied topically to a three-dimensional RhE model, comprised of non-transformed, human-derived epidermal keratinocytes, which have been cultured to form a multi-layered, highly differentiated model of the human epidermis. The RhE test method is based on the premise that corrosive chemicals are able to penetrate the stratum corneum by diffusion or erosion, and are cytotoxic to the cells in the underlying layers. Cell viability is measured by enzymatic conversion of the vital dye MTT [3-(4,5-Dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide, Thiazolyl blue tetrazolium bromide; CAS number 298-93-1], into a blue formazan salt that is quantitatively measured after extraction from tissues. Corrosive chemicals are identified by their ability to decrease cell viability below defined threshold levels.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin Corrosion","yearReceived":"2017","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:24","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Skin corrosion","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2015-04","shortName":"LabCyteCORNEAMODEL24 EIT","title":"LabCyteCORNEAMODEL24 eye irritation test","organisation":"JaCVAM - Japan","description":"This test method is based on commercial three-dimensional Human Cornea-Like Epithelium (RhCE) tissue constructs that are produced using either primary human epidermal keratinocytes. LabCyteCORNEAMODEL24 is used to evaluate the eye hazard potential of a test chemical based on its ability to induce cytotoxicity in a RhCE tissue construct, as measured by the tetrazolium dye.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2015","generalComments":"","protocolSop":"","lastUpdate":"Thursday, March 4, 2021 - 15:24","lastUpdateDate":"2021-03-04","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2019-05","shortName":"TPO-LUM","title":"Thyroid method 2b: Thyroperoxidase (TPO) inhibition based on oxidation of Luminol","organisation":"EURL ECVAM - European Union","description":"This method evaluates the activity of the thyroperoxidase (TPO), a key enzyme for the synthesis of thyroid hormones. The method allows to identify TPO-inhibiting compounds by assessing the enzyme activity in prepared extracts from FTC-238 cells transfected with human recombinant TPO. TPO activity is measured through the oxidation of luminol, resulting in a decrease in luminescence. This method was selected with other methods to assess modulating effects on the thyroid system (OECD, 2014). Information on these selected methods is available in TSAR as ‘Thyroid methods’.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Endocrine disruption","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 12:36","lastUpdateDate":"2026-04-02","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"In vitro","specificMethodologies":"Reporter gene assay; Enzyme/biochemical activity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2019-01","shortName":"ALIsens","title":"In vitro model for the prediction of respiratory sensitization of inhalable substances","organisation":"EURL ECVAM - European Union","description":"The test method is an in vitro assay intended for the prediction of respiratory sensitisation potential of airborne chemicals (including particulate matter and nano-materials). The method consists of a 3D in vitro system based on human cells cultured at the air-liquid interface (ALI). This system mimics the alveolar-capillary barrier and allows to assess substances with both low and high molecular weight (e.g. pollen or house dust mites).","stepStage":"Submission > Assessment of presubmission","workflowStep":"Submission","workflowStage":"Assessment of presubmission","topic":"Sensitisation","yearReceived":"2019","generalComments":"","protocolSop":"","lastUpdate":"Monday, June 21, 2021 - 14:21","lastUpdateDate":"2021-06-21","stage":"Test Submission","status":"Ongoing","code":"SUB_ASSESS","applicationDomain":"Mixed/general toxicology","endpoint":"Sensitisation — unspecified","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-12","shortName":"2-TA","title":"Two-tiered approach to determine the skin sensitising capacity and potency of chemicals","organisation":"EURL ECVAM - European Union","description":"The 2-TA tiered approach addresses the capacity and the potency of a potentially sensitizing chemical on acute exposure to the chemical. Human-derived epidermal-like cells (NCTC2544) are used to distinguish skin sensitizers from respiratory sensitizers and non-sensitizers (including irritants). This is the so-called 1st Tier or also called 'NCTC-assay'. The 2nd Tier or also called 'EE-potency assay' is used to estimate the potency of the identified sensitizing chemical. Human reconstituted epidermal skin-equivalents are used in this step. The NCTC-assay is based on the effects of skin sensitizing chemicals on the production of pro-inflammatory intracellular IL-18 by human-derived NCTC2544 keratinocytes. The EE-assay is based on the inverse correlation between potency of a sensitizer and the viability of a human reconstituted epidermal model as determined by the MTT test and IL- 1 alpha release into the culture medium.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Sensitisation","yearReceived":"2011","generalComments":"Submission closed because an improved version of the test method has been submitted under TM2012-05","protocolSop":"","lastUpdate":"Wednesday, November 11, 2020 - 10:26","lastUpdateDate":"2020-11-11","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Sensitisation — unspecified","methodology":"In vitro; Integrated approach; Mixed","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2004-07","shortName":"BALB/c 3T3 CTA","title":"In vitro BALB/c 3T3 Cell Transformation Assay","organisation":"EURL ECVAM - European Union","description":"The in vitro CTA using the BALB/c 3T3 cell line is aimed at detecting the carcinogenic potential of chemicals. The assay is based on the change of the phenotypic features of cells undergoing the first steps of the conversion from normal cells to neoplastic-like cell foci with oncogenic properties. Carcinogenesis is a complex multistage process by which normal cells are transformed into cancer cells characterised by an accumulation of changes at the cellular, genetic and epigenetic level. In vitro CTAs such as the BALB/c 3T3 CTA have been shown to recapitulate a multistage process that closely models some stages of in vivo carcinogenesis. Cell transformation in all the systems studied to-date involves changes at each stage in order for progression to the next stage in the transformation process to occur. A minimum of four phenotypic stages appears to be involved in cell transformation. These include (from primary to fully malignant cells): 1) a block in cellular differentiation, 2) acquisition of immortality, characterised by unlimited lifespan, an aneuploidy karyotype and a decreased genetic stability; 3) acquisition of tumorigenicity, which is closely associated with the in vitro phenotypes of foci formation, anchorage independent growth in semi-solid agar and autocrine growth factor production; 4) full malignancy, including metastasis when the cells are injected into a suitable host, supporting the biological relevance of in vitro transformation to in vivo carcinogenicity. The assay is based on the change of the phenotypic features of transformed foci undergoing the first steps of the conversion from normal cells to neoplastic-like cells with oncogenic properties.","stepStage":"Regulatory acceptance/Standards > Stopped","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Stopped","topic":"Carcinogenicity","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=137","lastUpdate":"Monday, October 26, 2020 - 15:26","lastUpdateDate":"2020-10-26","stage":"Regulatory assessment","status":"Rejected","code":"REG_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Carcinogenicity","methodology":"In vitro","specificMethodologies":"Cell transformation assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2000-01","shortName":"CFU-GM","title":"The Colony Forming Unit-Granulocyte/Macrophage Assay for predicting acute neutropenia in humans","organisation":"EURL ECVAM - European Union","description":"The CFU-GM in vitro test detects the direct adverse effects of xenobiotics on the proliferative capacities of the progenitors and should be able to predict the exposure level of xenobiotics that would cause clinical neutropenia after onset acute exposure. The assay is used in a screening mode to predict chemical induced myelosuppression, one of the haematological parameters to be considered for the assessment of the haematotoxic potential of chemical compounds of various kinds.","stepStage":"Submission > Assessment finalised","workflowStep":"Submission","workflowStage":"Assessment finalised","topic":"Acute toxicity","yearReceived":"2000","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=101","lastUpdate":"Saturday, October 24, 2020 - 09:03","lastUpdateDate":"2020-10-24","stage":"Validation","status":"Finalised","code":"SUB_FINAL","applicationDomain":"Pharmaceutical","endpoint":"Acute toxicity","methodology":"In vitro","specificMethodologies":"Colony-forming assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-07","shortName":"Zebrafish assay","title":"Automated screening to detect cardiotoxicity in zebrafish","organisation":"EURL ECVAM - European Union","description":"Zebrafish embryos (48hpf) are exposed in a HTS system to test compounds and effects on heart rate, arrhythmia and death/fibrilation are automatically detected. The aim of the method is to identify compounds that induce arrhythmia and consequently present a potential risk of QT interval prolongation. In addition, compounds that induce non zERG-related cardiotoxicity should be identified, to be classified as generally cardiotoxic. The test is inteneded as screening method to detect cardiotoxicity of products in early stages of drug development.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Cardiotoxicity","yearReceived":"2009","generalComments":"Further information was requested, but was not provided.","protocolSop":"","lastUpdate":"Wednesday, October 21, 2020 - 16:22","lastUpdateDate":"2020-10-21","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Environmental; Pharmaceutical","endpoint":"Cardiotoxicity","methodology":"Other","specificMethodologies":"HTS; Embryo/developmental model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1995-01","shortName":"TER","title":"Rat skin transcutaneous electrical resistance test","organisation":"EURL ECVAM - European Union","description":"The assay is based on determining the effects of a chemical on the electrical resistance of rat skin (i.e. TER). A second endpoint is the ability of a dye to penetrate through rat skin following exposure to a chemical. The test can be used to identify potential corrosive chemicals or mixtures. It can also be used to identify chemicals that are non-corrosive when used in combination with other methods. Evidence indicates that TER measurements are predictive of severe cutaneous effects in vivo. The (later) addition of the dye to the test reduces false positives.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin Corrosion","yearReceived":"1995","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=115","lastUpdate":"Monday, October 19, 2020 - 14:53","lastUpdateDate":"2020-10-19","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin corrosion","methodology":"Ex vivo","specificMethodologies":"Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM2008-06","shortName":"CAMVA","title":"Chorioallantoic membrane vascular assay","organisation":"EURL ECVAM - European Union","description":"The CAMVA assay assesses the possible detrimental effects which potential eye irritants have on the blood vessels of the embryo's CAM (chorioallantoic membrane). In preparation of the test a small opening is cut into the shell of the egg four days after fertilization and a small amount of albumen is removed to allow optimal growth of the CAM. The opening is resealed and the eggs are incubated for a further 6 days. The age of the CAM used in the test has been limited to 10 days in order to comply with the legislation in the EU countries which prohibits experiments on chick embryos that are older than 10 days (Bagley et al., 1992, 1994). On day 10 the test substance is applied directly onto a small area of the CAM. After exposure for 30 minutes the eggs are examined for any vascular change in the CAM, e.g. haemorrhaging, hyperaemia (capillary injection) or the occurrence of vessels devoid of blood flow (ghost vessels). The concentration of test materials eliciting such damaging effects in 50 % of the eggs is calculated as toxicological endpoint.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"On hold-pending further information (under external validation)","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 11:13","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"Ex vivo","specificMethodologies":"Embryo/developmental model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2010-04","shortName":"IMOLA-IVD","title":"The IMOLA-IVD test method for eye irritation testing","organisation":"EURL ECVAM - European Union","description":"IMOLA-IVD is an automated platform for monitoring the vitality of living cells based on the Intelligent Mobile Lab In Vitro Diagnostics. It can detect changes in cellular metabolism after toxic exposure. It is an automatisation of the Cytosensor Microphysiometer (CM) toxicity test that was developed for the labeling of chemicals for eye corrosion/irritation and is an alternative to the Draize rabbit eye irritation test. The IMOLA-IVD consists of three elements: (i) the sensor system, (ii) the pumping and switching of fluids, (iii) a program which runs the protocol according to the CM toxicity test protocol and collects the data.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2010","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 12:57","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Metabolic activity sensor assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-10","shortName":"VitroDerm","title":"THOR VitroDerm RhE test method for skin irritation testing","organisation":"EURL ECVAM - European Union","description":"The Thor Vitroderm model is a 3-d reconstructed human epidermis seeded on a polycarbonate filter and cultured at the air liquid interface. After 17 days, highly differentiated and stratified epidermis has developed which comprises a proliferating basal cell layer of columnar epithelial cells, giving rise to morphologically distinct suprabasal spinous and granular layers and a functional stratum corneum. The purpose of the test method is for the prediction of acute skin irritation of chemicals applied topically to the apical surface of a reconstructed human epidermal model, by the measure of cytotoxicity by the MTT viability assay. The principle of the RHE model test is based on the premise that irritant chemicals are able to penetrate the stratum corneum and are cytotoxic to the cells in the underlying layers. Cell viability is measured by dehydrogenase conversion of the vital dye MTT [3-(4,5-Dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide, Thiazolyl blue; EINECS number 206-069-5, CAS number 298-93-1)] into a blue formazan salt that is quantitatively measured after extraction from tissues.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin irritation","yearReceived":"2009","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 11:10","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-02","shortName":"SenCeetox","title":"In vitro Method for Identifying Skin Sensitisers Combining Peptide Binding with ARE/EpRE Mediated Gene Expression in Human Skin Cells","organisation":"EURL ECVAM - European Union","description":"The SenCeeTox is an in vitro approach in which data on chemical reactivity towards Glutathione (GSH), gene expression profiling and cell viability are generated in order to identify the sensitisation potential of chemicals and to assign them into potency categories. The method is addressing two biological mechanisms: a) the reactivity towards proteins and b) the activation of the ARE/EpRE signaling pathways in human keratinocytes, both of which are considered to be relevant steps in the inductions phase of skin sensitisation. Protein reactivity is measured in a cell-free system whereas gene induction is measured by qRT-PCR using mRNA isolated from 3D human epidermis models. Viability of cells is measured in parallel with the MTT assay. Such parameters are used in combination in a weighted algorithm to derive an in vitro toxicity index (IVTI) that is then used to predict a sensitiser potency category.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2011","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 10:57","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro; In silico; In chemico; Mixed","specificMethodologies":"Omics; Reporter gene assay; AI/ML; Organoid/3D tissue model; Cytotoxicity/cell viability assay; Binding/interaction assay; Chemical reactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2012-05","shortName":"RHE IL-18","title":"RHE IL-18 potency test for skin sensitization","organisation":"EURL ECVAM - European Union","description":"The RHE IL-18 potency test for skin sensitization is an integration of two test methods covering epidermal inflammation and cytotoxicity with the aim to measure skin sensitizing potential and potency. It represents an update of the two-tiered approach, (2-TA; TM-2011-12). The RHE-IL18 allows the quantification of the two readouts (IL-18 release and cytotoxicity) in the same test system (Reconstructed human Epidermis (RhE)). The skin sensitisation potential is tested based on the quantification of the release of intracellular pro-inflammatory IL-18 in keratinocytes by ELISA. Skin sensitiser potency is measured as inverse correlation of cell viability (expressed as EC50 value). RHE IL-18 can be performed using commercially available RhE as well as in-house developed RhE.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2012","generalComments":"Invitation to send a full submission","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 10:56","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro; Integrated approach; Mixed","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Immunoassay/flow cytometry; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-13","shortName":"Skin absorption RHE","title":"Skin absorption based on RHE models","organisation":"EURL ECVAM - European Union","description":"The mechanistic principles for the uptake of chemicals into and through human skin and reconstructed human epidermis (RHE) are almost identical, the stratum corneum being the major barrier. Regarding morphology, immunohistochemistry and lipid composition RHE at current state is close to human epidermis. In addition, blood circulation does not play a role until the corium. In contrast to the skin of furry animals, in humans the shunt pathway of absorption via the hair follicles is of little relevance due to the low number. They are absent in RHE. The endpoints assessed in the test method are the permeation of the respective test substance through RHE and skin into the receptor medium as quantified by cumulated amount, μg/cm² and %, after 6 and 24 h. Using the infinite dose approach (282.5 μ l aqueous solution of the test substance per cm² skin) permeation coefficient Papp (cm/s) and lag-time (h) as further endpoints are derived from the linear part of the respective absorption curves by linear regression. In addition, the finite dose approach (10 μl of the test substance per cm² skin) was used to quantify the penetration of the test substance into the skin.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin absorption/penetration","yearReceived":"2008","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 11:01","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Skin absorption/penetration","methodology":"In vitro","specificMethodologies":"High-content imaging; Organoid/3D tissue model; Immunoassay/flow cytometry; Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-08","shortName":"DC-SRM","title":"Multiplexed SRM (Selected Reaction Monitoring) Mass Spectrometric Assays for Targeted Quantification of Skin Sensitization Biomarkers in Dendritic Cell Models","organisation":"EURL ECVAM - European Union","description":"Multiplexed SRM (Selected Reaction Monitoring) is a Mass Spectrometric Assays for Targeted Quantification of Skin Sensitization Biomarkers in Dendritic Cell (DC) Models. The test is designed for dichotomous classification (Yes/No). The method comprises steps of contacting a relevant DC model, preferentially MUTZ-3 progenitor cells, with potential sensitizers, non-sensitizers and solvent controls, and measuring the change in protein expression using targeted mass spectrometric assays. MUTZ-3 are a human myelomonocytic cell line which was identified as the human dendritic cell (DC)-like cell line that is closest to human monocyte derived DC. The protein biomarker model for skin sensitization is based on detailed proteomic analysis of relevant cell lines. A panel of 15 most promising biomarkers allows discriminating between sensitizers and non-sensitizers. Additional 10 biomarkers allow to identify respiratory sensitizers in MUTZ-3 cells","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Sensitisation","yearReceived":"2011","generalComments":"On hold-pending further information","protocolSop":"","lastUpdate":"Friday, October 16, 2020 - 10:50","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Sensitisation — unspecified","methodology":"In vitro","specificMethodologies":"Omics","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2010-05","shortName":"IVM","title":"Bovine Oocyte Maturation Assay","organisation":"EURL ECVAM - European Union","description":"The bovine in vitro maturation test assesses oocyte maturation. The method is based on the use of immature oocytes from bovine animals. The physiology of the bovine reproductive cycle is more similar to humans than conventional laboratory animals for a number of reproductive parameters including kinetics of oocyte growth, oocyte size, mechanisms of ovulation and maturation, timing of fertilisation and first cleavage, kinetics of pre- and post-implantation development, mechanisms of gastrulation, cell cycle and gestation length. Finally, at the genetic level, the homologies between human and cattle are higher than human and rodent, The toxicological endpoint evaluated is the completion of meiosis up to the metaphase II stage, which is reached after 24h in in vitro culture. The analysis is based on microscopic inspection. Matured oocytes are characterised by the extrusion of the first polar body associated to the second metaphase stage. The assay investigates the potential for interaction of a chemical substance with meiosis and as such investigates events within an adverse outcome pathway (AOP) associated with perturbation of fertilisation. Such assay could be used within an Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of reproductive toxicants.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Reproductive toxicity, In vitro fertilisation","yearReceived":"2010","generalComments":"On hold-pending further information","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=129","lastUpdate":"Friday, October 16, 2020 - 10:48","lastUpdateDate":"2020-10-16","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity","methodology":"In vitro; Integrated approach; Ex vivo; Mixed","specificMethodologies":"High-content imaging; Embryo/developmental model; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-02","shortName":"SkinEthic RHE","title":"Skinethic Skin Irritation Test-42bis","organisation":"EURL ECVAM - European Union","description":"The SkinEthic™ Skin Irritation Test (42 minutes application + 42 hours post-incubation) is designed for the prediction of acute skin irritation potential of chemicals by measurement of their cytotoxic effect, as reflected by MTT assay, on the Reconstructed Human Epidermis (RHE).","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Skin irritation","yearReceived":"2008","generalComments":"Validation finalised, OECD Test Guideline / EU Test Method available","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=135","lastUpdate":"Monday, October 12, 2020 - 09:03","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"VAL_PEER_FINAL","applicationDomain":"Cosmetics","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-01","shortName":"Modified EpiDerm SIT","title":"Modified EpiDerm Skin Irritation Test for Hazard Identification and Labelling of Chemicals According to EU Classification System","organisation":"EURL ECVAM - European Union","description":"The Modified EpiDerm SIT is an in vitro method that has been developed and optimized to predict the skin irritation potential of chemicals according to EU classification system. The method utilizes a commercially available three-dimensional tissue construct EpiDermTM (EPI-200) produced by MatTek Corporation (US). The test consists of a topical exposure of the neat test article to a human reconstituted epidermis model for 60 min. During the 60 minute exposure period, the treated epidermis is first left at room temperature for 25 minutes and subsequently incubated for 35 min at 37°C. At the end of exposure, the test article is removed from the epidermis and the tissue is incubated for an additional 42h to express the resulting damage. Cell viability is measured by dehydrogenase conversion of MTT [(3-4,5-dimethyl thiazole 2-yl) 2,5-diphenyltetrazoliumbromide], taken up by cell mitochondria, into a blue formazan salt that is quantitatively measured after extraction from tissues. Relative tissue viability is determined against the concurrent negative control-treated tissues. Tissues treated with skin irritants (R38) are expected to show a relative viability of less than 50% while non-irritants show a viability greater than 50%. A concurrent positive control is used with each assay. The modified EpiDerm SIT has been adopted together with EpiSkinTM (SM), SkinEthic™ RHE, LabCyte EPI-MODEL24 SIT test methods, and included in OECD TG 439 which describes an in vitro procedure that may be used for the hazard identification of irritant chemicals (substances and mixtures) in accordance with the UN Globally Harmonized System of Classification and Labelling (GHS) Category 2.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Skin irritation","yearReceived":"2008","generalComments":"Validation finalised, OECD Test Guideline / EU Test Method available","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=138","lastUpdate":"Monday, October 12, 2020 - 09:03","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"VAL_PEER_FINAL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2006-02","shortName":"Ocular Irritection","title":"Ocular Irritection","organisation":"EURL ECVAM - European Union","description":"The Ocular Irritection test method addresses the eye irritation and serious eye damage endpoint. It intends to identify chemicals potentially inducing eye irritation and/or serious eye damage on the basis of the United Nations (UN) Global Harmonized Systems for classification and labelling (GHS), as well as those not inducing ocular toxicity. The test system is composed of a macromolecular reagent containing a mixture of proteins and glycoproteins, carbohydrates, lipids and low molecular weight components. After rehydration, this reagent forms a macromolecular matrix, which mimics the cornea. The test chemical is applied on a membrane disc which delivers it to the matrix. Chemicals being ocular toxic will induce a turbidity of the macromolecular matrix by interacting with its components and disrupting its conformation. The Ocular Irritection protocol is intended to be potentially used for the prediction of acute eye irritation and serious eye damage in regulatory safety testing under the UN GHS, REACH, EU Classification, Labelling and Packaging of substances and mixtures (CLP) or Cosmetic Directive for chemicals. Currently, the sequential TD and BU approaches are considered for taking place in a wider strategy such as an Integrated Approach on Testing and Assessment (IATA). This IATA would be similar to the already validated one for skin irritation and corrosion. If validated—e.g., at the OECD—this ocular toxicity strategy may be included in a revised version of the \"REACH Guidance on Information Requirements and Chemical Safety Assessment\" published by ECHA.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Serious eye damage/Eye irritation","yearReceived":"2006","generalComments":"Revised Test Submission Template on the Ocular Irritection® test method proposed for Peer Review","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=157","lastUpdate":"Monday, October 12, 2020 - 09:08","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"Integrated approach; In chemico; Mixed","specificMethodologies":"Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2005-04","shortName":"EpiSkin™ - RHE","title":"Reconstructed Human Epidermis Model Test","organisation":"EURL ECVAM - European Union","description":"The EpiSkin™ model is a three dimensional reconstructed human epidermis that, once established, comprises of a main basal, supra basal, spinous and granular layers and a functional stratum corneum (the outer barrier layer of skin). The use of the model specifically for skin irritation testing involves the topical application of a test chemical followed by an assessment of cell viability, and specifically cytotoxicity (as measured via the MTT assay). Reductions in cell viability are then expressed as a % of the negative control. The % reduction is then used to predict the irritation potential of a chemical. A substance is considered to be irritating to skin (i.e. categorised as R38) if tissue viability after exposure and post incubation (see protocol, below) is less than or equal to 50%. Cell viability above 50% is considered a marker of a chemical being a non-irritant.","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Skin irritation","yearReceived":"2005","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=131","lastUpdate":"Monday, October 12, 2020 - 09:09","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Not applicable","code":"REC_NA","applicationDomain":"Cosmetics","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-13","shortName":"CryoHeps","title":"Cytochrome P450 (CYP) enzyme induction in vitro method using the cryopreserved human hepatocytes","organisation":"EURL ECVAM - European Union","description":"The human cytochrome P450 (CYP) enzyme induction method assesses the potential of test chemicals to induce the activity of three CYP enzymes (CYP1A2, CYP2B6 and CYP3A sub-family) in cryopreserved primary human hepatocytes. At the molecular level, CYP enzyme induction is a process controlled by a set of nuclear receptors associated with downstream signal transduction pathways. Experimentally, at the end of cell exposure to the test chemical, a cocktail of three specific CYP enzymatic substrate probes is applied to the cells and CYP enzyme induction is assessed through the measurement of of the specific metabolites formation by CYP1A2, 2B6 and 3A sub-family by analytical liquid chromatography/mass spectrometry (LC/MS) technique. The CYP enzyme induction in vitro methods (see also TM2009-14) are reliable and relevant methods for the generation of human metabolism data in animal-free testing strategies assessing adverse health effects of xenobiotics.","stepStage":"Validation > Initiated","workflowStep":"Validation","workflowStage":"Initiated","topic":"Toxicokinetics","yearReceived":"2009","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=193","lastUpdate":"Tuesday, October 20, 2020 - 14:04","lastUpdateDate":"2020-10-20","stage":"Regulatory assessment","status":"Rejected","code":"VAL_INIT","applicationDomain":"Pharmaceutical","endpoint":"Toxicokinetics","methodology":"In vitro","specificMethodologies":"Analytical chemistry readout; Enzyme/biochemical activity assay; Binding/interaction assay","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2007-01","shortName":"Epics SCT","title":"Epidermal Skin Corrosion Test 1000","organisation":"EURL ECVAM - European Union","description":"The EpiCS (previously called EST-1000) Skin Corrosion Test (SCT) can be used to assess the potential of chemicals to cause skin corrosion. The epiCS model is a reconstructed epidermis consisting of proliferating and differentiating keratinocytes. The test is based on the notion that skin corrosion is in part due to cytotoxic effects of chemicals. As such, it involves the exposure of the cells to test chemicals and subsequent determination of cytotoxicity via the MTT assay. The MTT assay is used to determine cytotoxicity, which is then expressed as a % of the negative control. A positive control is also included in the assay. The test is available as a commercial kit.","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Skin Corrosion","yearReceived":"2007","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:07","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REC_NA","applicationDomain":"Cosmetics","endpoint":"Skin corrosion","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1999-05","shortName":"ToBI TET","title":"Toxin Binding Inhibition test for batch potency testing of tetanus vaccines for human use","organisation":"EURL ECVAM - European Union","description":"The ToBI TET measures antibody levels against erysipelas in the serum of guinea pigs immunised with tetanus vaccine for human use. It is carried out for vaccine batch release to demonstrate the tested batch complies with the requirements set in the marketing authorisation for the given vaccine.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Quality control of vaccines","yearReceived":"1999","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:19","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Vaccine quality control","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1999-04","shortName":"ELISA TET","title":"ELISA test for batch potency testing of tetanus vaccines for human use","organisation":"EURL ECVAM - European Union","description":"The ELISA TET measures antibody levels against tetanus in the serum of guinea pigs immunised with tetanus vaccine for human use. It is carried out for vaccine batch release to demonstrate the tested batch complies with the requirements set in the marketing authorisation for the given vaccine.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Quality control of vaccines","yearReceived":"1999","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:20","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Vaccine quality control","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2002-02","shortName":"Cryo-WBT-IL1","title":"In Vitro Pyrogen Test using Human Cryopreserved Whole Blood/IL-1 Beta","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using Human Cryopreserved Whole Blood/IL-1 Beta Cryo-WBT-IL1) is a monocyte activation test (MAT) used to detect or quantify substances that activate human monocytes or monocytic cells to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines have a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement for the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=134","lastUpdate":"Monday, October 12, 2020 - 09:16","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Pyrogenicity","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2002-05","shortName":"WBT-IL6","title":"In Vitro Pyrogen Test using Human Whole Blood/IL-6","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using Human Whole Blood/IL-6(WBT-IL6) is a monocyte activation test (MAT) applied to detect or quantify substances that activate human monocytes or monocytic cells to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines have a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement for the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:16","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Pyrogenicity","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2002-03","shortName":"MM6 IL6","title":"In Vitro Pyrogen Test using MonoMac 6 cells/IL-6","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using MonoMac 6 cells/IL-6 (MM6-IL6) is a monocyte activation test (MAT) applied to detect or quantify substances that activate human monocytes or monocytic cells (here the cell line MonoMac 6) to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines have a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement for the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:17","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Pyrogenicity","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2002-01","shortName":"WBT-IL1","title":"In Vitro Pyrogen Test using Human Whole Blood/IL-1 Beta","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using Human Whole Blood/IL-1 Beta (WBT-IL1) is a monocyte activation test (MAT) applied to detect or quantify substances that activate human monocytes or monocytic cells to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines play a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement of the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=133","lastUpdate":"Monday, October 12, 2020 - 09:17","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Pyrogenicity","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2002-04","shortName":"PBMC-IL6","title":"In Vitro Pyrogen Test using Peripheral Blood Mononuclear Cells/IL-6","organisation":"EURL ECVAM - European Union","description":"The In Vitro Pyrogen Test using Peripheral Blood Mononuclear Cells/IL-6 (PBMC-IL6) is a monocyte activation test (MAT) applied to detect or quantify substances that activate human monocytes or monocytic cells to release pro-inflammatory cytokines, for example tumour necrosis factor alpha (TNFα), interleukin-1 beta (IL-1β) and interleukin-6 (IL-6). These cytokines have a role in fever pathogenesis. Consequently, the MAT can detect the presence of pyrogens in the test sample. The MAT is suitable, after a product-specific validation, as a replacement for the rabbit pyrogen test or the bacterial endotoxin test (Limulus amebocyte lysate assay).","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Pyrogenicity","yearReceived":"2002","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:17","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Pyrogenicity","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2005-05","shortName":"THRESH FISH","title":"Threshold approach for acute fish toxicity testing","organisation":"EURL ECVAM - European Union","description":"The Threshold Approach for Acute Fish Toxicity testing is a tiered testing strategy and is based on the fact that the LC50/EC50 value of the most sensitive of the three test species (fish, algae and invertebrates) is commonly used for hazard and risk assessment and that fish is often not the most sensitive test species. When fish acute toxicity data need to be generated, the fish limit test as described in OECD TG 203 / C.1 should be carried out at a threshold concentration using far less fish than the full LC50 test. The threshold concentration corresponds to the lowest LC50/EC50 derived from reliable acute invertebrate (e.g. Daphnia, OECD TG202) and algae (e.g. OECD TG 201) data. If no fish mortality is observed at the threshold concentration, it demonstrates that that the fish is not the most sensitive test species. No further testing is required and the TC value can be used as LC50 fish (LC50 fish is greater than TC with 99% of confidence). If mortality occurs at the threshold concentration, a full LC50 test should be conducted.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Fish acute toxicity","yearReceived":"2005","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:09","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Environmental","endpoint":"Aquatic toxicity","methodology":"Integrated approach; In vivo; Mixed","specificMethodologies":"Cytotoxicity/cell viability assay; Integrated testing strategy/battery; In vivo reduction/refinement assay","review":"AI-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM1998-03","shortName":"EpiDerm™","title":"EpiDerm™ skin corrosivity test","organisation":"EURL ECVAM - European Union","description":"The test method is based on the commercially available EpiDerm™ model, a reconstructed human epidermal model grown from human-derived epidermal keratinocytes which are cultured to form a multilayered and highly differentiated model of the human epidermis. The corrosivity potential of chemicals is assessed with the measurement of their citotoxic effects on EpiDerm™ model.","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Skin Corrosion","yearReceived":"1998","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=119","lastUpdate":"Monday, October 12, 2020 - 09:22","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REC_NA","applicationDomain":"Cosmetics","endpoint":"Skin corrosion","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1998-02","shortName":"EpiSkin™","title":"EpiSkin™ skin corrosivity test","organisation":"EURL ECVAM - European Union","description":"The EpiSkin™ skin corrosivity test can be used to identify whether (or not) a chemical has the potential to corrode skin. Skin corrosion is generally defined as full thickness destruction of skin tissue but can also include any irreversible alterations to skin. The method uses a 3D human skin model and involves topical application of a test substance and subsequent assessment of cell viability and cytotoxicity. The method is based on the EpiSkin™ standard model, which is a three-dimensional human skin model that is comprised of a reconstructed epidermis and a functional stratum corneum (i.e. the outer layer of skin). For the purposes of testing for skin corrosion potential, substances are applied topically to the surface of the model and then cell viability is assessed. Specifically, cytotoxicity is assessed through the MTT assay.","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Skin Corrosion","yearReceived":"1998","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=118","lastUpdate":"Monday, October 12, 2020 - 09:22","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REC_NA","applicationDomain":"Cosmetics","endpoint":"Skin corrosion","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1998-01","shortName":"Corrositex®","title":"In Vitro Membrane Barrier Test Method for Skin Corrosion","organisation":"EURL ECVAM - European Union","description":"The Corrositex® method was originally established to predict the skin corrosivity potential of chemicals and to rank them according to their degree of corrosive effect. The assay is based on the determination of the time needed for a test material to pass through a biobarrier membrane. The membrane is a reconstituted collagen matrix with physical properties that are similar to rat skin. The end-point is the time required to cause a colour change in an underlying 'chemical detection system'. The colour change is visually scored and therefore a subjective measurement (i.e. there is a potential variation in measurement outcomes due to operator variability). The test method has received regulatory approval as a replacement of in vivo skin corrosivity tests (i.e. the Draize rabbit skin test) for specific classes of chemicals (i.e. acids, bases and certain derivatives) which meet the technical requirements of the assay.","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Skin Corrosion","yearReceived":"1998","generalComments":"In the 1990s, the Corrositex® method was evaluated on a number of occasions by agencies in the US. They concluded that in specific testing circumstances, the method would be useful as a stand-alone assay for evaluating skin corrosion potential.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=116","lastUpdate":"Monday, October 12, 2020 - 09:23","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REC_NA","applicationDomain":"Cosmetics","endpoint":"Skin corrosion","methodology":"In vitro; Ex vivo; In chemico; Mixed","specificMethodologies":"Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2008-10","shortName":"EpiOcular EIT","title":"EpiOcular™ Human Cell Construct EIT","organisation":"EURL ECVAM - European Union","description":"The EpiOcular™ Eye Irritation Test (EIT) consists of a reconstructed human cornea-like epithelium (RhCE) tissue construct, a non-keratinized multi-layered epithelium prepared from non-transformed, human-derived epidermal keratinocytes which show a cornea-like structure analogous to that found in in vivo. The test chemical is applied topically to a minimum of two RhCE tissue constructs. Following the exposure and post-treatment incubation periods, tissue viability is assessed by MTT assay.","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=164","lastUpdate":"Monday, October 12, 2020 - 09:04","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REC_NA","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2015-03","shortName":"SkinEthic HCE EIT","title":"SkinEthic™ HCE Eye Irritation Test","organisation":"EURL ECVAM - European Union","description":"The SkinEthic™ Human Corneal Epithelium (HCE) Eye Irritation Test (EIT) method is an in vitro assay used for assessing eye irritation/serious eye damage. The method uses a reconstructed human cornea-like epithelium (RhCE) consisting of a multilayered epithelium prepared from immortalized human corneal epithelial cells which reproduce the multi-layer organization of the human cornea. The tissues are exposed to the test chemicals according to two possible protocols, depending on the physical state of the test chemical either solid \"EITS\" protocol (see DB-ALM protocol No.191), or liquid/viscous \"EITL\" protocol ( see DB-ALM protocol No.190).","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Serious eye damage/Eye irritation","yearReceived":"2015","generalComments":"External validation performed. Report submitted for peer-review as full test submission.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:10","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REC_NA","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1997-01","shortName":"TABST","title":"Deletion of Target Animal Batch Safety Test","organisation":"EURL ECVAM - European Union","description":"Since 1st April 2013, the TABST is no longer required in Europe and has been deleted from the European Pharmacopoeia monographs for veterinary vaccines. Since 2005, the target animal batch safety test could be waived when a sufficient number (e.g. 10) of batches had been found to comply with the test. International - VICH: Two VICH guidelines on harmonisation of criteria to waive target animal batch safety testing for inactivated (VICH GL50R) and live (VICH GL55) vaccines for veterinary use are in force since in May 2017 and should be implemented by May 2018. An earlier version of VICH GL50R had been in force since 2013. By meeting the requirements outlined in VICH GL50R and 55, vaccine manufacturers can now apply for a waiver of the TABST by their national competent authorities.","stepStage":"Recommendation > Not applicable","workflowStep":"Recommendation","workflowStage":"Not applicable","topic":"Quality control of vaccines","yearReceived":"1997","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:24","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REC_NA","applicationDomain":"Food safety","endpoint":"Vaccine quality control","methodology":"In vivo","specificMethodologies":"In vivo reduction/refinement assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2005-01","shortName":"MNvit","title":"In vitro mammalian cell micronucleus test","organisation":"EURL ECVAM - European Union","description":"The in vitro micronucleus (MNvit) test is a short-term genotoxicity assay for the detection of micronuclei in the cytoplasm of interphase cells. Micronuclei may originate from acentric chromosome fragments (i.e. lacking a centromere), or whole chromosomes that are unable to migrate to the poles during the anaphase stage of cell division. Therefore the MNvit test is an in vitro method that provides a comprehensive basis for investigating chromosome damaging potential in vitro because both aneugens and clastogens can be detected in cells that have undergone cell division during or after exposure to the test chemical. Micronuclei represent damage that has been transmitted to daughter cells.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Genotoxicity/Mutagenicity","yearReceived":"2005","generalComments":"This study represents the first retrospective validation carried out by ECVAM","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:09","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"Micronucleus/genotoxicity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2001-01","shortName":"ELISA ERY","title":"ELISA test for batch potency testing of swine erysipelas vaccines","organisation":"EURL ECVAM - European Union","description":"The ELISA ERY measures antibody levels against erysipelas in the serum of mice immunised with inactivated swine erysipelas vaccine. It is carried out for vaccine batch release to demonstrate that the given vaccine batch complies with the requirements set in the marketing authorisation for the given vaccine.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Quality control of vaccines","yearReceived":"2001","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:18","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Food safety","endpoint":"Vaccine quality control","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2015-02","shortName":"Ashland RhE SIT","title":"Ashland Skin Irritation Test","organisation":"EURL ECVAM - European Union","description":"This test is based on the in vitro test system of Reconstructed Human Epidermis (RHE), which closely mimics the biochemical and physiological properties of the upper parts of the human skin. Cells used are primary keratinocytes isolated from human skin. Irritant compounds induced reversible cell damage which can be measured after short time application (42 minutes) and long post incubation (42 hours). Cell viability in RHE models is measured by enzymatic conversion of the vital dye MTT 3-(4,5- Dimethylthiazol-2-yl)-2,5-diphenyltetrazolium bromide. After solubilisation Thiazolyl blue is measured by optical density. Cell viability of compound is compared to negative control (DPBS) to define percent of viability (end point). Compound is classified irritant if viability is under 50%. This test allows testing of chemical compounds to class them into 2 subgroups (irritant and non irritant) for cosmetics and pharmaceutical application. There is an impact in terms of the Three Rs principle because this method avoids using animal to test irritant compounds. It’s an alternative method to cutaneous Draize test so it replaces animal testing.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Skin irritation","yearReceived":"2015","generalComments":"Similar test method to already validated and accepted ones. Not considered for follow-up","protocolSop":"","lastUpdate":"Wednesday, October 14, 2020 - 09:08","lastUpdateDate":"2020-10-14","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Cosmetics; Pharmaceutical","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Enzyme/biochemical activity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2004-04","shortName":"RBC","title":"Red Blood Cell haemolysis","organisation":"EURL ECVAM - European Union","description":"The Red Blood Cell (RBC) test is used to examine ocular irritants by measuring lysis of erythrocytes (haemolysis) and denaturation of released oxyhaemoglobin. The RBC test is a cell-based cytotoxicity assay, which allows assessing membrane damage of erythrocytes (haemolysis) and changes of the oxyhaemoglobin configuration (protein denaturation). To determine haemolysis, the haemoglobin leakage is measured spectrophotometrically.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Serious eye damage/Eye irritation","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=99","lastUpdate":"Friday, October 16, 2020 - 10:42","lastUpdateDate":"2020-10-16","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Cytotoxicity/cell viability assay; Analytical chemistry readout; Ex vivo/tissue-based assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2004-03","shortName":"NRR","title":"Neutral Red Release Assay","organisation":"EURL ECVAM - European Union","description":"The Neutral Red Release (NRR) assay is a quantitative colorimetric cytotoxicity test using cell lines to measure the immediate toxic effect of a test substance on the cell membrane, resulting in a leakage of intracellular contents. If cells in culture are preloaded with vital dye (neutral red [NR]) and then exposed to a toxic substance, the amount of dye released from the cells will reveal the degree of membrane damage. The result of the test is expressed as the concentration of test substance that gives rise to the release of 50% of the NR from preloaded cells. Cell membrane damage is one of the principal events that lead to chemical-induced eye irritation, and it can be modelled using the NRR assay.","stepStage":"Peer-review > Ongoing","workflowStep":"Peer-review","workflowStage":"Ongoing","topic":"Serious eye damage/Eye irritation","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=54","lastUpdate":"Friday, October 16, 2020 - 10:42","lastUpdateDate":"2020-10-16","stage":"Validation","status":"Finalised","code":"VAL_PEER_ONGO","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-05","shortName":"MUSST","title":"Myeloid U937 Skin Sensitisation Test","organisation":"EURL ECVAM - European Union","description":"The MUSST assay supports the discrimination between sensitizing and non-sensitizing chemicals. It addresses one of the biological mechanisms described under key event 3 (events in dendritic cells (DC)) of the skin sensitization Adverse Outcome Pathway (AOP) by measuring the induction of the CD86 protein marker in U937 cells. The U937 cells are human myeloid cells used as surrogate model for DCs. U937 is a cell line established from a diffuse histiocytic lymphoma with the advantage of higher stability and the easiness of maintenance compared to human-blood derived DCs. The CD86 protein marker is a costimulatory factor which is upregulated in mature DCs and plays a pivotal role in antigen presentation and subsequent T cell priming. In the MUSST test method, the modulation of the FITC-labeled anti-CD86 in U937 cells is measured by flow cytometry after a 48 hours exposure to test chemicals.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2009","generalComments":"Validation stopped. New submission with new protocol received under TM2013-02 (U-Sens)","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:59","lastUpdateDate":"2020-10-12","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-11","shortName":"ERalpha-CALUX","title":"Prediction of the in vivo estrogenic activity of chemicals ERalpha-CALUX","organisation":"EURL ECVAM - European Union","description":"The ERalpha-CALUX test is an estrogen receptor transactivation assay, assessing the activity of (anti-)estrogenic compounds. The test is based on the human osteocarcinoma cell line (U2OS). The cells are stably co-transfected with the full length human ERα and a luciferase gene. The test assesses the transcription of the luciferase gene, through the measurement of luminescence, and allows the discrimination between agonists and antagonists. This assay investigates the potential for interaction of a chemical substance with nuclear receptors for endogenous hormones and as such investigate early events within an adverse outcome pathway (AOP) associated with perturbation of the endocrine system. It could be used within an Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of endocrine disruptors.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2009","generalComments":"Not prioritised for validation by ECVAM. External validation performed.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:00","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"VAL_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro; Integrated approach; In vivo; Mixed","specificMethodologies":"Reporter gene assay; Binding/interaction assay; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2004-01","shortName":"Cytosensor","title":"The cytosensor microphysiometer toxicity test","organisation":"EURL ECVAM - European Union","description":"The cytosensor microphysiometer toxicity test method is a cell-based in vitro assay that was developed as a partial replacement of the Draize rabbit eye irritation test. The method consists of a monolayer of adherent mouse L929 fibroblast cells that are cultured on a polycarbonate cell culture insert. Within the system there is also a light-sensitive pH sensor. The ocular toxicity of test substances is evaluated according to reductions in metabolic rate of the cells following exposure (as assessed by changes in the rate of reduction of pH in the cell culture medium). The cells have a natural rate of metabolism that results in the production of extra-cellular acids. This rate is expected to vary following exposure to potentially toxic substances.","stepStage":"Regulatory acceptance/Standards > Stopped","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=130","lastUpdate":"Thursday, April 2, 2026 - 13:04","lastUpdateDate":"2026-04-02","stage":"Regulatory assessment","status":"Rejected","code":"REG_STOP","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Metabolic activity sensor assay","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2009-12","shortName":"OPIV","title":"In vitro approach for organophosphorous compounds-induced neurotoxicity (OP Neurotox Assay)","organisation":"EURL ECVAM - European Union","description":"In vitro test system based on in SH-SY5Y human neuroblastoma cell line was proposed for evaluation of organophosphorus compounds (OPs) induced neurotoxicity. The assay is based on the measurements of acetylcholineesterase (AChE) and neuropathy target esterase (NTE) activity since OPs exert neurotoxicities following inhibition of these two critical esterases: AChE for acute toxicity and neurotoxic esterase NTE for delayed neuropathy. To be effective insecticides, AChE needs to be inhibited, but NTE does not. The relationship between AChE and NTE inhibition provides information on which OP compounds could be expected to be effective as insecticides without them causing progressive, irreversible delayed neuropathy in humans and susceptible animals. Concentration-responses of AChE and NTE activities can be measured in cultured neuronal cells, plotted against the log of their concentrations, and a ratio of the concentrations responsible for 50% inhibition (IC50) determined by dividing the NTE IC50 by the AChE IC50. Ratios >100 suggest that NTE inhibition and subsequent delayed neuropathy are unlikely because test compound concentrations would need to be 100-fold higher than those causing acute toxicity. Protoxicants can be tested in this system following incubation with 0.05% bromine solution or rat liver microsomes. NTE and AChE inhibition can be measured following either a single exposure or exposures for up to 28 days. Use of this in vitro system would decrease the need to dose animals and collect brain and spinal cord for esterase measurements. Evaluated organophosphorus compounds were chosen based on animal studies that identified them as active toxicants capable of producing delayed neuropathy (n=6), protoxicants capable of producing delayed neuropathy (n=3), active AChE inhibitors not producing delayed neuropathy in unprotected animals (n=5), and protoxicants not producing delayed neuropathy in unprotected animals (n=5). The in vitro test comparing the NTE inhibition with the AChE inhibition produced by the 19 compounds tested matched the in vivo results 100% of the time.","stepStage":"Submission > Assessment of full submission","workflowStep":"Submission","workflowStage":"Assessment of full submission","topic":"Neurotoxicity","yearReceived":"2009","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:00","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_ASSESS","applicationDomain":"Mixed/general toxicology","endpoint":"Neurotoxicity","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay; Enzyme/biochemical activity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2010-06","shortName":"DRG","title":"Embryonic Rat Dorsal Root Ganglia Organotypic Culture","organisation":"EURL ECVAM - European Union","description":"Rat Dorsal Root Ganglia (DRG) explants from 15-day-old embryos (E15) were proposed as a model for studying peripheral neuropathy induced by drugs belonging to different classes. The parameter measured at each time point (24 hours after the drug treatment) was the length of longest neurite of each DRG evaluated by the program Image J in the control culture and after exposure to a drug. Drug-induced neurotoxicity assessment was based on the ability of E15 DRG explants to measure an outgrowth of neurites (length) when exposed to NGF and at the same time to a toxic substance (drug). E15 DRG represents a suitable model for assessing the neurotoxicity of antineoplastic drugs because in vivo DRG are the main target of several neurotoxic drugs and the concentrations of the drugs used to elicit changes in this in vitro model were, in general, comparable to those achievable in vivo. The model has been tested treating DRG cultures with two antineoplastic drugs (paclitaxel and oxaliplatin) belonging to two different classes of antineoplastic agents and known to be both neurotoxic in clinical use and in animal models. DRG has been treated with concentrations comparable to those achievable in vivo. Neurotoxic drug concentrations induced a reduction of neurite length higher than 50% respect to control that represents the cut-off value of the test. The results obtained confirmed the neurotoxicity evidenced with the same drugs in published rat and mouse in vivo models. Intended purpose of the test method could be relevant to regulatory and scientific neurotoxicity testing for antineoplastic drugs in industry-driven compounds early screening and discovery.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Neurotoxicity","yearReceived":"2010","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:53","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical","endpoint":"Neurotoxicity","methodology":"In vitro; Ex vivo; In vivo; Mixed","specificMethodologies":"High-content imaging; Organoid/3D tissue model; Embryo/developmental model","review":"AI-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM2014-04","shortName":"devTOXqP","title":"devTOX qp (Stemina) devTOX quick Predict","organisation":"EURL ECVAM - European Union","description":"This is an in vitro developmental toxicity method that could be used to evaluate whether a test compound may have the potential for teratogenicity in humans. The test method measures changes in a ration between two metabolic biomarkers (cystine and ornithine) present in cell culture media of human induced undifferentiated pluripotent stem (hiPS) cells exposed to a compound. Changes in two metabolites, ornithine and cystine, are measured in response to treatment and then used in a ratio (o/c ratio) across an 8-point dose response curve. The teratogenicity potential is the interpolated exposure level (concentration) of a test compound where the dose response curve crosses a defined teratogenicity threshold. Exposure levels greater than this concentration are associated with teratogenicity. Its performance suggests that the assay is amenable to predicting teratogens regardless of their classification as weak or strong. Cytotoxicity is provided as a secondary endpoint at the same eight concentrations as those tested for the o/c ratio. The design and sensitivity of the assay allows for identification of teratogenic potential at non-cytotoxic levels of the test compound, by negating the confounding effects of changes in metabolite abundance due solely to cytotoxicity. The assay is performed with undifferentiated human iPS cells, providing an opportunity to evaluate disruptions in human development.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Teratogenicity","yearReceived":"2014","generalComments":"Not considered for validation studies based on PARERE consultation opinion.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:37","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Industrial chemicals","endpoint":"Teratogenicity","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2012-02","shortName":"Skin PAMPA","title":"Skin PAMPA Permeability System","organisation":"EURL ECVAM - European Union","description":"The Skin PAMPA is a method that measures the passive permeation of a substance, applied in solution or as a formulation, through an artificial membrane mimicking the human skin. The test is performed in a 96 well plate and the membrane is placed between a donor compartment, to which the test solution/formulation is applied, and a receptor compartment filled with buffer solution at pH 7.4 (simulation of blood pH). The permeation (passive diffusion) through the membrane is measured by determining the portion of substance appearing in the receptor compartment after incubation. Quantification is done with a suitable analytical method, such as UV-Vis spectrophotometry or Liquid-chromatography. The applied artificial membrane has been specifically designed to mimic the human stratum corneum (SC) that forms the major barrier of skin. It contains a synthetic structural analogue similar to the ceramide component of the skin-lipid matrix and other components such as cholesterol and free fatty acids. The manufacturing technology used for the artificial membrane aims at creating a similar hydrophilic/lipophilic balance as found in the natural SC lipid matrix. The production of the membrane does not require human or animal tissue.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin permeability/penetration","yearReceived":"2012","generalComments":"Submission on hold.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:43","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Skin permeability/penetration","methodology":"In chemico","specificMethodologies":"HTS; Analytical chemistry readout; Barrier/permeability/transport assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2013-03","shortName":"SS Predictor","title":"Skin Sensitizer Predictor","organisation":"EURL ECVAM - European Union","description":"The Skin Sensitizer Predictor is a test method proposed for skin sensitisation hazard assessment. The expression levels of mRNA transcripts for a set of four genes and of proteins involved in three different intracellular signalling pathways are quantified following treatment of a mouse foetal skin-derived dendritic cell (DC) line (FSDC) with test chemicals. Readouts are then used in a prediction model based on linear discriminant analysis to derive a Prediction Score for distinguishing between sensitising and non-sensitising chemicals. The FSDC cell line used is reported to possess antigen presenting capacity and to have a surface phenotype consistent with immature myeloid DC precursors. The quantitative analysis of m-RNA expression levels for the four genes investigated is performed by real time reverse transcription polymerase chain reaction (RT-PCR) and the protein levels are determined by chemiofluorescence analysis following separation with western blotting. Of the four genes measured, the expression of three of them (TRXR1, HMOX1 and NQO1) is controlled by the Nrf2/ARE/EpRE pathway which is a relevant pathway involved in skin sensitisation as documented in the scientific literature. The fourth gene investigated encodes the CXCL10 chemokine which plays an important role in T-cell mediated immune responses. The intracellular signalling proteins measured are reported to be involved in the p38, MAPK and JNK signalling pathways which have been shown to be activated in DC and keratinocytes upon exposure to protein binding chemicals.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2013","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:40","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"In vitro; In silico; Mixed","specificMethodologies":"Omics; Reporter gene assay; AI/ML; Immunoassay/flow cytometry; Binding/interaction assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-03","shortName":"PorCORA","title":"Porcine corneal opacity reversibility assay","organisation":"EURL ECVAM - European Union","description":"Porcine corneal opacity reversibilitThe Porcine Corneal Opacity Reversibility Assay (PorCORA) evaluates recovery of ocular irritation in excised, cultured, porcine corneas. Like the Draize rabbit eye test, substances are applied directly to the corneal surface and then corneal recovery is evaluated over a period of 21 days. Corneal injury and reversibility are determined by scoring the area of sodium fluorescein (NaFL) stain retention 1, 2, 3, 7, 10, 14, and 21 days post-exposure. NaFL retention is a well-characterized indicator of tissue damage and, more specific to the cornea, loss of the surface epithelial layer integrity. The endpoint of this assay is a time to corneal recovery score (days). A test substance can therefore be characterized as causing reversible or irreversible corneal damage. Re-epithelialization is the primary method of corneal healing. Because this multi-layered epithelial process is driven by replenishment of cells from the corneal periphery, a replacement test using whole, intact corneas is critical to an accurate assessment of corneal recovery and reversibility. In addition, the PorCORA air-interface culture technique is imperative for maintenance of normal in vivo corneal physiology. PorCORA has been developed for the purpose of replacement of the reversibility component of the Draize rabbit eye test. In combination with in vitro tests that quantify the severity of ocular injury and vascular effects, PorCORA could replace in vivo ocular irritation tests.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:04","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2014-07","shortName":"CORNiPSC","title":"iPSC-derived corneal epithelial cells for ocular toxicity tests","organisation":"EURL ECVAM - European Union","description":"The CORNiPSC is intended to be used for eye irritation testing. It is an in vitro method that applies corneal epithelial cells produced from human induced pluripotent stem cell (iPSC) lines and grown in a two-dimensional cell culture. The endpoint measurement is done by determination of cell viability. This test method is in a presubmission stage. Further refinement of the testing protocol in the light of the addressed key endpoint, will show, if this test method could be useful in the initial step of either a Bottom-Up or a Top-Down approach to be used in an integrated testing strategy.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Serious eye damage/Eye irritation","yearReceived":"2014","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:37","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro; Integrated approach; Mixed","specificMethodologies":"Cytotoxicity/cell viability assay; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2004-02","shortName":"FL","title":"The fluorescein leakage test method","organisation":"EURL ECVAM - European Union","description":"Various cell types can form tight junctions when cultured in vitro. In the case of the fluorescein leakage test method, Madin Derby Canine Kidney (MDCK) cells can do this in a manner that is very similar to tight junctions found in epithelial cells in the eye and specifically the cornea. This creates a largely impermeable barrier that most chemicals cannot cross. This is also applies to fluorescein, which is a dye that is normally blocked by MDCK cells. In the method, the MDCK cells are grown to confluence (i.e. there are tight junctions between cells) on porous filters and then exposed to a test chemical. Leakage is then assessed by measuring how much fluorescein passes through the cell layer. As such the method tries to model the disruption of the integrity. The test method can be used to assess chemicals and substances that might disrupt tight junctions between epithelial cells that make up the cornea and similar constructs within the eye.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Serious eye damage/Eye irritation","yearReceived":"2004","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=71","lastUpdate":"Monday, October 12, 2020 - 09:13","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"VAL_FINAL","applicationDomain":"Cosmetics","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1999-01","shortName":"EST","title":"Embryonic Stem Cell Test","organisation":"EURL ECVAM - European Union","description":"The embryonic stem cell system has been developed as a screening test for potentially embryotoxic substances. Disturbances of embryonic stem cell differentiation following treatment of xenobiotics indicate a potential of embryotoxicity for early pre-implantation stages of mammalian development.","stepStage":"Submission > Not applicable","workflowStep":"Submission","workflowStage":"Not applicable","topic":"Reproductive toxicity, Embryotoxicity","yearReceived":"1999","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=113","lastUpdate":"Wednesday, October 21, 2020 - 16:12","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"SUB_NA","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Embryotoxicity","methodology":"In vitro","specificMethodologies":"Embryo/developmental model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1999-02","shortName":"MM","title":"Micromass Embryotoxicity Assay","organisation":"EURL ECVAM - European Union","description":"The micromass test is based on detecting the ability of toxic chemical compounds to inhibit the formation of cell foci. Embryonic limb mesenchyme or Central Nervous System (CNS) cells (usually mid-brain, which form foci of neurons) from chicken, mouse or rat can be used for the micromass test. The primary culture of limb bud cells of mammalian origin reproduces cartilage histogenesis, a fundamental step in the morphogenesis of the skeleton. When cultured at high cell densities, the cells differentiate to form foci of chondrocytes and neurones, respectively. Various functions, including cell proliferation, cell differentiation, cell to cell communication and cell to extracellular matrix interactions are implicated in this developmental process and the differentiation in vitro and in vivo is very similar both in terms of cell morphology and the specific macromolecules synthesised. The inhibition of mammalian embryogenesis and cell differentiation in vitro is an indication of a potential risk of teratogenicity in vivo. Thus, these cultures were used as a short-term assay system for the prediction of an embryotoxic potential in presence or in absence of a metabolic activating system.","stepStage":"Submission > Not applicable","workflowStep":"Submission","workflowStage":"Not applicable","topic":"Reproductive toxicity, Embryotoxicity","yearReceived":"1999","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=122","lastUpdate":"Wednesday, October 21, 2020 - 16:11","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"SUB_NA","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Embryotoxicity","methodology":"In vitro","specificMethodologies":"High-content imaging; Embryo/developmental model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1999-03","shortName":"WEC","title":"Postimplantation Rat Whole-Embryo Culture Assay","organisation":"EURL ECVAM - European Union","description":"Rat embryos with 1 to 5 somites are used in this method. In general, these embryos are relatively sensitive for xenobiotics as compared to older embryos. During 48 hours of culture, major aspects of organogenesis occur, including e.g. heart development, closure of the neural tube, development of ear and eye, brachial bars and limb buds. Interference during this period may lead to general retardation of growth and development or to specific malformations in one or several organ anlagen. Embryos are cultured in rotating containers, thus facilitating the exchange of the culture medium with the gaseous phase above. The latter is essential for optimal oxygenation of the culture medium in view of the increasing demand for oxygen of the embryo. After culture, the morphology of the embryos is carefully assessed. Comparison of control embryos with exposed embryos forms the basis for conclusions regarding the embryotoxicity of tested compounds.","stepStage":"Submission > Not applicable","workflowStep":"Submission","workflowStage":"Not applicable","topic":"Reproductive toxicity, Embryotoxicity","yearReceived":"1999","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=123","lastUpdate":"Wednesday, October 21, 2020 - 16:10","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"SUB_NA","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Embryotoxicity","methodology":"In vitro; Ex vivo; Mixed","specificMethodologies":"High-content imaging; Embryo/developmental model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-02","shortName":"MELN","title":"Transactivation assay for detection of compounds with (anti)estrogenic potential using MELN cells","organisation":"EURL ECVAM - European Union","description":"The MELN test is an estrogen receptor transactivation assay, assessing the activity of (anti-)estrogenic compounds. The test is based on the human mammary adenocarcinoma cell line (MCF-7). The cells endogenously express the estrogen receptor alpha (ERα), and are stably transfected with a luciferase reporter gene. The test assesses the transcription of the luciferase gene, through the measurement of luminescence, and allows the discrimination between agonists and antagonists. This assay investigates the potential for interaction of a chemical substance with estrogenic nuclear receptors for endogenous hormones and as such investigates early events within an adverse outcome pathway (AOP) associated with perturbation of the endocrine system. Such assay could be used within Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of endocrine disruptors.","stepStage":"Validation > Stopped","workflowStep":"Validation","workflowStage":"Stopped","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2009","generalComments":"Validation stopped after consultation with test submitter","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:01","lastUpdateDate":"2020-10-12","stage":"Validation","status":"Discontinued","code":"VAL_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro; Integrated approach; Mixed","specificMethodologies":"Reporter gene assay; Binding/interaction assay; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-09","shortName":"epiCS SIT","title":"epiCS Skin Irritation Test","organisation":"EURL ECVAM - European Union","description":"The epiCS RHE SIT test method addresses the skin irritation endpoint. It intends to make predictions of skin irritancy potential on the basis of the United Nations (UN) Global Harmonized Systems for classification and labelling (GHS). The test system is composed of Reconstructed human Epidermis (RhE) tissues. This model constitutes a three dimensional structure which reproduces the typical multi-layer cell organization of the epidermis. The tissues are exposed to the test chemicals during 20 minutes. This is followed by a post-exposure period of 24±2 hours in order to derive the cell viability of the tissues. Mitochondrial dehydrogenases of living cells are able to reduce the MTT reagent into blue formazan. The Sterlab RHE SIT protocol measures the optical density (OD) of the blue formazan in the treated tissues. The OD is normalised to the one of the negative control in order to express cell viability values in percentages. Test chemicals lead to a positive response when the cell viability values are below or equal to 50%, while a negative response is found when cell viability values are above 50%. On the basis of the UN GHS a positive response should be labelled as \"Classified\" whereas a negative response should be labelled as \"Not Classified\". A prediction as \"Classified\" means that the test chemical could be either a skin irritant or a skin corrosive. The epiCS RHE SIT protocol is intended to be potentially used for the prediction of acute skin irritation in regulatory safety testing under the UN GHS, REACH, EU Classification, Labelling and Packaging of substances and mixtures (CLP) or Cosmetic Directive for chemicals. The OECD published an \"Integrated Approach on Testing and Assessment (IATA) for Skin Corrosion and Skin Irritation\" which shows how proper interpretation of skin irritation and skin corrosion tests should be performed and how additional tests should be eventually conducted to evaluate the skin irritation and corrosion potential of chemicals. The ECHA published the \"REACH Guidance on Information Requirements and Chemical Safety Assessment\" which makes reference to this OECD IATA and includes a testing strategy based on it.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin irritation","yearReceived":"2009","generalComments":"ESAC peer review requested additional testing","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:02","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin irritation","methodology":"In vitro; Integrated approach; Mixed","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2013-02","shortName":"U-SENS™","title":"U-SENS™ - Myeloid U937 Skin Sensitisation Test","organisation":"EURL ECVAM - European Union","description":"The U-SENS assay supports the discrimination between sensitizing and non-sensitizing chemicals. It addresses one of the biological mechanisms described under key event 3 (events in dendritic cells (DC)) of the skin sensitization Adverse Outcome Pathway (AOP) by measuring the induction of the CD86 protein marker in U937 cells. The U937 cells are human myeloid cells used as surrogate model for DCs. U937 is a cell line established from a diffuse histiocytic lymphoma with the advantage of higher stability and the easiness of maintenance compared to human-blood derived DCs. Although being of monocytic origin, U937 cells have shown DC-like responses following exposure to sensitizers including the up-regulation of surface marker (e.g. CD86) and cytokine production (e.g. TNF-a). The up-regulation of CD86 plays important roles in the induction of Allergic Contact Dermatitis (ACD). The CD86 protein marker is a costimulatory factor which is upregulated in mature DCs and plays a pivotal role in antigen presentation and subsequent T cell priming. It is one of the most frequently used biomarkers in in vitro assays indicating DC activation and has been shown to be the most suitable and robust marker in U937 cells. In the U-SENS™ test method, the modulation of the CD86 membrane marker in U937 cells is measured by flow cytometry after a 45 hours exposure to test chemicals.","stepStage":"Validation > Finalised","workflowStep":"Validation","workflowStage":"Finalised","topic":"Skin sensitisation","yearReceived":"2013","generalComments":"The U-SENS™ test method was formely called Myeloid U937 Skin Sensitisation Test (MUSST) (TM 2009-05).","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=183","lastUpdate":"Monday, October 12, 2020 - 08:41","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"VAL_FINAL","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2010-02","shortName":"PALM cell assay","title":"Transactivation assay for detection of compounds with (anti)androgenic potential using PALM cells","organisation":"EURL ECVAM - European Union","description":"The \"PALM\" test is an androgen receptor transactivation assay, assessing the activity of (anti-)androgenic compounds. The test is based on a human prostate cancer cell line (PC-3). The cells are stably co-transfected with the full length human androgen receptor (AR) and a luciferase reporter gene. The test assesses the transcription of the luciferase gene, through the measurement of luminescence, and allows the discrimination between agonists and antagonists. These assays investigate the potential for interaction of a chemical substance with nuclear receptors for endogenous hormones and as such investigate early events within an adverse outcome pathway (AOP) associated with perturbation of the endocrine system. Such assays could be used within an Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of endocrine disruptors.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2010","generalComments":"Not prioritised for validation by ECVAM due to issues regarding the material transfer agreement","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:54","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro; Integrated approach; Mixed","specificMethodologies":"Reporter gene assay; Binding/interaction assay; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2010-01","shortName":"ARBA","title":"Rat recombinant androgen receptor binding assay for the detection of compounds with (anti)androgenic potential","organisation":"EURL ECVAM - European Union","description":"The Androgen Receptor Binding Assay (ARBA) uses a rat recombinant protein, comprising the hinge region and Ligand Binding Domain (LBD) of the receptor, tagged with thioredoxin. It should be noted that the amino acid sequence of the rat receptor is homologous to the human one. This test measures the capability of a chemical to bind to the androgen receptor, by using a radioactive readout. The binding assays do not allow discrimination between agonists and antagonists. The assay is a non-cell based assay. These assays investigate the potential for interaction of a chemical substance with nuclear receptors for endogenous hormones and as such investigate early events within an adverse outcome pathway (AOP) associated with perturbation of the endocrine system. Such assays could be used within an Integrated Testing Strategy (ITS) or Integrated Approaches to Testing and Assessment (IATA) for identification of endocrine disruptors.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2010","generalComments":"Not prioritised for validation by ECVAM","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:54","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Endocrine disruption","methodology":"In vitro; Integrated approach; Mixed","specificMethodologies":"Binding/interaction assay; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2014-01","shortName":"RTgill-W1","title":"Fish cell line acute toxicity test","organisation":"EURL ECVAM - European Union","description":"The rainbow trout gill (RTgill-W1) cell line assay is a cytotoxicity test which has the potential to predict fish acute toxicity. Gill cells were chosen for this assay since gills are one of the main barriers between the fish and its surrounding water. Therefore fish gills are a major target site for environmental toxicants. RTgill-W1 cells are seeded into 24-well plates and are incubated for 24 hours to attach and form a monolayer. Then they are exposed to a series of test chemical concentrations for a period of 24 hours. Exposure is performed with a minimal essential medium (L-15/ex) not containing bovine serum whereas normal L-15 cell culture medium containing bovine serum is used for the initial incubation. Cytotoxicity is determined using a combination of three endpoints representing cell viability: cellular metabolic activity measured with AlamarBlue, cell membrane integrity measured with 5-carboxyfluorescein diacetate acetoxymethyl ester (CFDA-AM) and lysosomal membrane integrity measured with Neutral Red. Cell viability is expressed in % of the negative control. The respective EC50 value is calculated for each endpoint and EC50 calculation is based on measured exposure concentration. The most sensitive of the three endpoints is used for prediction of fish acute toxicity (based on 35 chemicals tested at the time of the submission EC50 would correspond to LC in fish). Acute fish toxicity tests are e.g. part of the data requirements for REACH (10t or more) and are often required for safety testing of effluents. The RTgill-W1 cell line assay should support prediction of acute fish toxicity. Chemicals with a specific neurotoxic mode of action and compounds that may be activated via metabolism were found to cause less toxicity in RTgill-W1 cells compared to fish.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Fish acute toxicity","yearReceived":"2014","generalComments":"","protocolSop":"","lastUpdate":"Wednesday, October 14, 2020 - 09:52","lastUpdateDate":"2020-10-14","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Environmental; Industrial chemicals","endpoint":"Aquatic toxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-07","shortName":"DCMA","title":"Dendritic Cell Migration Assay for distinguishing sensitizers from non-sensitizers (including irritants)","organisation":"EURL ECVAM - European Union","description":"The Dendritic Cell Migration Assay (DCMA) is an in vitro method for the identification of sensitisers based on the evaluation of Denditric Cells migration. It is designed for dichotomous classification (S/NS) and does not provide additional information on potency. DCMA addresses the migration of Langerhans Cells (LC) from the epidermis to the regional lymph nodes which is considered to be one of the key events involved in the induction of skin sensitization. The migration is associated with increased levels of the CXCR4 receptor and decreased levels of the CCR5 receptor on maturing LC, and with increased secretion of the chemokine CXCL12 by dermal fibroblasts. Driven by the CXCR4-CXCL12 interaction, the maturing LCs eventually travel from the dermis to the lymph nodes where they prime T cells and induce sensitization. This process is mimicked in vitro using human keratinocyte and fibroblast cultures in a two compartment test system, and is simplified by replacing the fibroblasts by the recombinant counterparts of the chemokines involved (CXCL12 and CCL5). The test is based on the human myelomonocytic cell line MUTZ-3 which was identified as the human dendritic cell-like cell line that is closest to human monocyte derived DC (high functional relevance). MUTZ-3 cells are differentiated into immature MUTZ-LC. They are then fluorescently labelled with CSFE. On the basis of the differential migration (amount of fluorescent MUTZ-LC entering the lower transwell) skin and lung sensitisers are discriminated from non-sensitisers and irritants. If the chemical is a sensitizer, MUTZ-LC will mature, up-regulate CXCR4 and preferentially migrate towards CXCL12. If the chemical is an irritant, no up-regulation of CXCL12 occurs, CCR5 expression is maintained and MUTZ-LC preferentially migrate towards CCL5.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Sensitisation","yearReceived":"2011","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:50","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Sensitisation — unspecified","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-11","shortName":"CPA-I test","title":"CPA-I test","organisation":"EURL ECVAM - European Union","description":"The CPA-I test aims to identify the proteins associated with type I (IgE mediated) hypersensitivity reactions. The immune response in hypersensitivity reactions towards proteins are mainly of IgE/Th2 cell type (i.e. the type I hypersensitivity reaction). The CPA-I exploits inherent characteristics of proteins, which enable them to polarize the subsequent immune response- as demonstrated by the production of neopterin, a specific immune modulator. The test utilizes a human myleomonocytic cell line, that is cultivated for 48 hrs in the presence of serial dilutions (within the range of non- toxic concentrations) of the test substance. Supernatants are collected and the concentration of neopterin is measured using ELISA. For each substance, a dose response curve is established. The cells are cultivated in serum free media. Cell viability is determined by propidium iodide (PI). The potential allergens to be tested can be tested as component of extracts or in pure native form.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2008","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:06","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Cytotoxicity/cell viability assay; Immunoassay/flow cytometry","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-14","shortName":"In vitro STS","title":"In vitro sensitisation testing strategy","organisation":"EURL ECVAM - European Union","description":"In vitro STS describes the use of a testing strategy based on existing methods that has a sufficient predictive capacity to be used as a stand-alone method for sensitisation testing. It addresses the first three key events (KE) of the of the skin sensitization Adverse Outcome Pathway (AOP). These key events are measured by formally validated and peer-reviewed methods, i.e. KE1 protein binding: DPRA (OECD TG 442C), KE2 keratinocyte activation: KeratinosensTM (OECD TG 442D), LuSens (ESAC reviewed) and KE3 dentritic cell activation: h-CLAT (OECD TG 442E), MUSST (ESAC reviewed). These methods constitute the main components of the testing strategy.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Skin sensitisation","yearReceived":"2011","generalComments":"Not considered for follow-up, skin sensitisation IATAs are currently being addressed in the OECD Task Force on Hazard Assessment","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:51","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin sensitisation","methodology":"In vitro; Integrated approach; In chemico; Mixed","specificMethodologies":"Binding/interaction assay; Chemical reactivity assay; Integrated testing strategy/battery","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-12","shortName":"Valitox","title":"Valitox an alternative in vitro toxicity assay","organisation":"EURL ECVAM - European Union","description":"Fluorescent method that allows for analysis of cell death through plasma membrane permeation detection. The cell impermeant SYTOX DNA binding dye was used. In dying or dead cells the dye crosses the plasma membrane, reaches the nucleus and binds DNA leading to an increase of fuorescent signal. The concentration of a chemical that is lethal to 50% of HeLa cells (LC50) is calculated. The ultimate aim is to predict acute human toxicity. This method was later officially submitted as DAP (Dequenching after photobleaching cytotoxicity test). See TM2011-01","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Acute toxicity","yearReceived":"2008","generalComments":"This method was later officially submitted as DAP (Dequenching after photobleaching cytotoxicity test). See TM2011-01","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 09:06","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity","methodology":"In vitro; In chemico; Mixed","specificMethodologies":"Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay; Bioaccessibility/bioelution assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2006-01","shortName":"ZFET","title":"Zebrafish embryo acute toxicity test for acute fish toxicity testing","organisation":"EURL ECVAM - European Union","description":"The zebrafish embryo acute toxicity test method (ZFET) is carried out with newly fertilised eggs from zebrafish (Danio rerio). It is an acute test that uses short-term exposure (96 hours) and determines the concentration of a chemical that is lethal to 50% of zebrafish embryos (LC50) as a prediction of acute fish toxicity. The following observations indicate death of an embryo: coagulation of the embryo, lack of somite formation, non-detachment of the tail and/or lack of heartbeat.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Fish acute toxicity","yearReceived":"2006","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=140","lastUpdate":"Monday, October 12, 2020 - 09:08","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Environmental","endpoint":"Aquatic toxicity","methodology":"In vivo","specificMethodologies":"Cytotoxicity/cell viability assay; Embryo/developmental model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2015-01","shortName":"HAD BoNT","title":"Hemi-Diaphragm Assay (HDA) for detection and quantification of botulinum neurotoxins (BoNT)","organisation":"EURL ECVAM - European Union","description":"The Hemi-Diaphragm Assay (HDA) is an ex vivo assay using phrenical hemidiaphragm preparations from mice for detection and quantification of botulinum neurotoxins (BoNT). BoNT inhibit the release of acetylcholine from peripheral nerve endings and this inhibition can be detected in isolated nerve-muscle preparations, e.g. phrenical hemidiaphragm preparations. The tissue preparation is maintained in an organ bath. Via ring electrodes the nerve is stimulated by an electric pulse followed by muscle contraction. The contraction amplitude is recorded and decreases when BoNT acts in the nerve endings. The time period between application of toxin and half maximum contraction amplitude (inflection point) is read out parameter. The variants of BoNT can be identified by specific antibodies. The submitter claims that the HDA test is applicable to analyse food and environmental samples for contamination with BoNT, human or veterinarian samples (blood and stool) in case of suspicious intoxications (e.g. bioterrorism), to test cosmetic and pharmaceutical products containing BoNT for batch release, to analyse human sera for specific anti-BoNT antibodies that may appear after treatment with BoNT and the test is a valuable tool in research. In many cases, mice are used for this purpose, developing Botulism disease in the presence of BoNT and subsequently die due to respiratory failure. The phrenical hemidiaphragm preparations are derived from humanely killed mice. Apart from the refinement aspect, the submitter claims that the HDA has reduction potential.","stepStage":"Submission > Not considered for validation","workflowStep":"Submission","workflowStage":"Not considered for validation","topic":"Detection of contaminations","yearReceived":"2015","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Wednesday, October 14, 2020 - 09:14","lastUpdateDate":"2020-10-14","stage":"Test Submission","status":"Discontinued","code":"SUB_NOTVAL","applicationDomain":"Cosmetics; Environmental; Pharmaceutical; Food safety","endpoint":"Contamination detection","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay","review":"AI-reviewed","threeR":"Reduction","literature":"Complete","verificationNote":""},{"id":"TM2014-05","shortName":"LUCS","title":"Light Up Cell Systems","organisation":"EURL ECVAM - European Union","description":"In vitro test method designed to predict and classify acute and geno-toxicity. The test method measures nucleic acid alteration in live cells through fluorescence readout in 96- or 384-well plates. The underlying cellular mechanism involves DNA and/or RNA damage by Reactive Oxygen Species (ROS). It takes advantage of the ROS-induced variations in fluorescence intensities in cells incubated with a membrane-permeant nucleic acid sensor of the cyanine asymmetrical family. It is proposed as a replacement of the 3T3-NRU assay in all its applications including phototoxicity and applicable also to skin corrosion and irritation regulatory testing under REACH cosmetics and biocides.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Acute toxicity","yearReceived":"2014","generalComments":"Not prioritised for validation by ECVAM since it has not fulfilled ECVAM requirements.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:35","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Acute toxicity","methodology":"In vitro","specificMethodologies":"Omics; HTS; Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-01","shortName":"DAP assay","title":"Dequenching after photobleaching cytotoxicity test","organisation":"EURL ECVAM - European Union","description":"DAP assay is a quantitative live cell cytotoxicity assay based on measurements on DNA alterations, which are assessed by the ability of DNA fluorophobes to establish different toxicity-dependent quenching levels in cells. The technology used is based on fluorescence Dequenching After Photobleaching. Therefore, DAP is a mechanistic-based assay that addresses DNA alterations in association (or not) with cell death. The protocol used is straightforward (single-step, no washings) and has been set up in HTS cell culture formats (96/384 well microplates). Mammalian or fish cell models (suspension or adherent) have been used e.g. HepG2, Caco-2 and primary cells. The results are expressed as IC50 values calculated from the concentration response curves using the following sigmoidal dose-response regression model: Y=Bottom + (Top-Bottom)/[1+10^(LogIC50-X)]. The following prediction model was established: Log(human blood LC50) = 0.967 x Log(DAP IC50) - 0.824. The DAP technology is presented as potentially applicable to several toxicological areas such as acute toxicity, genotoxicity, chronic toxicity and carcinogenicity. The immediate application could be for human acute toxicity, although this has not been explicitly shown. For the other areas of application experimental data are lacking.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Acute toxicity, Chronic toxicity, Genotoxicity/Mutagenicity","yearReceived":"2011","generalComments":"Submission closed because replaced by another version of the test method in subsequent submission (TM2014-05)","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:52","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Environmental","endpoint":"Acute toxicity; Chronic toxicity; Genotoxicity","methodology":"In vitro; In silico; In chemico; Mixed","specificMethodologies":"HTS; AI/ML; Cytotoxicity/cell viability assay; Phototoxicity/photoreactivity assay; Bioaccessibility/bioelution assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2010-08","shortName":"GGA","title":"Transcriptomics based Genomics-Genotox assay","organisation":"EURL ECVAM - European Union","description":"The Genomics-genotox assay is a transcriptomics-based in vitro test performed in HepG2 cells to accurately predict the in vivo genotoxic properties of chemicals. Mechanistic relevance of the classifier genes is represented by the fact that many of those genes are regulated by relevant transcription factors, such as the DNA damage response-related SP1 gene for the Ames-positive classifiers, and the involvement in stress response pathways for the Ames-negative classifiers. Stratification of the compounds based on the Ames- test, further adds mechanistic relevance, as it grossly separates compounds that are DNA-reactive (either direct or after metabolic activation) from those that are not reactive.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Genotoxicity/Mutagenicity","yearReceived":"2010","generalComments":"Does not qualify for entering validation","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:55","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro; In silico; Mixed","specificMethodologies":"Omics; AI/ML; Biomarker/DNA damage assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2014-03","shortName":"MucilAir","title":"Transepithelial permeability assessment using an in vitro cell model of the human airway epithelium","organisation":"EURL ECVAM - European Union","description":"MucilAir is an in vitro 3D reconstructed human tissue that includes a bronchial and a nasal epithelial model, which phenotypically and functionally are representative of in vivo human bronchial and nasal epithelium (ciliated cells, basal cells, goblet cells, presence of cilia and cilia-beating, and functional muco-ciliary clearance). It is cultured at an air -liquid interface and it is designed to measure how fast a specific part of the human upper airways absorbs the test substance. This method provides Papp (apparent permeability) values for the upper airways. Therefore, it appears to be relevant from the perspective of assessing systemic or internal exposure to a test substance via the respiratory route. The test method has potential for deriving relevant absorption parameters for the respiratory tract important for human toxicokinetic evaluation of test substances. However, the exact method to be used for this purpose and the data analysis model is not clearly indicated.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Respiratory permeability/penetration, toxicokinetics, Toxicokinetics","yearReceived":"2014","generalComments":"Considered to be followed up in the wider context of ADME methods","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:38","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical","endpoint":"Respiratory permeability/penetration; Toxicokinetics","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-04","shortName":"Bioaccess","title":"Bioaccessibility testing from powder and massive samples of metals and alloys","organisation":"EURL ECVAM - European Union","description":"The bioaccessability test method enables the quantification of metal species released into artificial solutions (artificial body fluids of relevance for exposure routes including inhalation and ingestion, and dermal contact) from metal or alloy particles or massive sheet at a specific loading and time periods. The released metal species are measured by determining total dissolved metal concentrations in particle-free solutions (leaching analysis). These concentrations can be related and compared with available toxic endpoints for the specific route of interest (inhalation, ingestion, dermal contact), exposure time, particle loading or surface area. Further in-depth studies, also considering surface properties of the particles, speciation of released metals, and mechanisms of release, as well as comparison to some in vivo tests could allow prediction of toxicity of other alloy particles and grouping of materials. The test method is proposed to be used for classification, ranking, and screening of different metal and alloy particles or massive sheet (relative comparison). Such data cannot be estimated based on bulk alloy compositions. It is claimed that the data generated with the test method can be used to estimate the impact of alloying on the behaviour of various alloying elements and indicate whether or not hazards associated with one or more of the constituents are likely to persist for the alloy. With regard to the regulatory framework REACH is mentioned.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Bioaccessibility","yearReceived":"2011","generalComments":"Not considered for follow-up.","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 10:00","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Industrial chemicals","endpoint":"Bioaccessibility","methodology":"In chemico","specificMethodologies":"Read-across/WoE; Bioaccessibility/bioelution assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2012-01","shortName":"Tettox","title":"Combined assay for the detection of tetanus toxicity in tetanus toxoids","organisation":"EURL ECVAM - European Union","description":"This functional assay is designed to detect active tetanus neurotoxin (TeNT) in vaccines containing a tetanus toxoid component. Only active TeNT would inhibit neurotransmitter release from neuronal cells leading to symptoms of tetanus disease detected with the in vivo assay. TeNT molecules consist of two subunits: a heavy chain which is responsible for the binding to target cells, and a light chain (L-chain) with a proteolytic domain which specifically cleaves the neuronal protein synaptobrevin-2, and thus inhibits neurotransmitter release. These two functional properties of the active TeNT molecules are measured in a stepwise approach: First, the test sample is incubated on a microtiter plate coated with the TeNT receptor (i.e. ganglioside GT1b). Active TeNT binds to the receptor, while molecules lacking a functional receptor domain are removed by washing. The bound TeNT molecules are treated with a reducing agent to release and activate the L-chains. The supernatant containing the activated L-chains is then transferred to a second microtiter plate containing recombinant synaptobrevin-2 (rSyb2) which is specifically cleaved by the active L-chains. The resulting cleavage fragment is detected using a cleavage-site specific antibody. Signal amplification is obtained by employing a biotinylated secondary antibody followed by peroxidase-coupled streptavidin, and tetramethylbenzidine is used as colorimetric substrate for quantification of the peroxidase. The absorbance is measured at 450 nm against 620 nm as reference wavelength. Absorption values of the test sample are determined and the decision on toxicity is based on statistical comparison to (historical) control samples. The European Pharmacopoeia monographs for tetanus vaccines for human or veterinary use stipulate that vaccine manufacturer demonstrate the absence of active TeNT during quality control of their products. The tests described are based on guinea pigs. The in vitro assay has the potential to replace the test in guinea pigs.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Quality control of vaccines","yearReceived":"2012","generalComments":"This assay, now named BINding And CLEavage (BINACLE) assay is undergoing formal validation within the Biological Standardisation Programme of EDQM (BSP136: Tetanus Toxoid BINACLE assay).","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:43","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Food safety","endpoint":"Vaccine quality control","methodology":"In vitro; In vivo; Mixed","specificMethodologies":"HTS; Immunoassay/flow cytometry; Analytical chemistry readout; Enzyme/biochemical activity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2013-01","shortName":"IVCP assay","title":"In vitro Caco-2 permeability","organisation":"EURL ECVAM - European Union","description":"The Caco-2 permeability assay measures the permeability of compounds through a human intestinal epithelial cell barrier. Therefore, the endpoint measured is intestinal permeability (expressed as apparent permeability - Papp value). The test method appears more relevant for drug permeability studies. The use of in vitro epithelial cell culture methods to estimate intestinal permeability is already foreseen in the FDA Guidance for Industry \"Waiver of In Vivo Bioavailability and Bioequivalence Studies for Immediate-Release Solid Oral Dosage Forms Based on a Biopharmaceutics Classification System (BCS)\". This guideline explains how to demonstrate the suitability of a permeability method intended for application of the BCS. The permeability coefficient across Caco-2 cell monolayer may be used to assign a drug substance to BCS class. It may also be used to estimate the oral absorption of new chemical entities. Compounds exhibiting apparent permeability < 1x10-6 [cm/s], 1-10x10-6 [cm/s] and > 10x10-6 [cm/s], can be classified as poorly (0-20%), moderately (20-70%) and well (70-100%) absorbed drugs, respectively. It is claimed that in some cases (presumably drugs) the method may replace the use of preliminary in vivo bioavailability or bioequivalence tests on animals.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Intestinal permeability/penetration, toxicokinetics, Toxicokinetics","yearReceived":"2013","generalComments":"Considered to be followed up in the wider context of ADME methods","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=142","lastUpdate":"Monday, October 12, 2020 - 08:41","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Pharmaceutical; Industrial chemicals","endpoint":"Intestinal permeability/penetration; Toxicokinetics","methodology":"In vitro","specificMethodologies":"Barrier/permeability/transport assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2007-03","shortName":"3T3 NRU","title":"3T3 Neutral Red Uptake cytotoxicity assay","organisation":"EURL ECVAM - European Union","description":"The 3T3 NRU cytotoxicity assay employs the BALB/c3T3 mouse fibroblast cell line and is based on the ability of viable cells to incorporate and bind the dye Neutral Red (NR), measured spectrophotometrically . The basic concept of basal cytotoxicity assays is that chemicals exert their toxic effects by disrupting structures and functions universal to all cells. The assay used the test method protocol and the IC50-LD50 regressions of the NRU cytotoxicity method, validated in the NICEATM/ECVAM validation study (see TM2003-01) and was proposed to identify chemicals that would not require classification for acute oral toxicity according to the EU CLP Regulation (i.e. LD50 > 2 000 mg/kg). It was envisaged that use of the 3T3 NRU test method to identify unclassified substances in a testing strategy, to support a read-across, or as part of a weight-of-evidence approach could potentially reduce the amount of animal testing for acute oral toxicity.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Acute toxicity, Basal Cytotoxicity","yearReceived":"2007","generalComments":"The validation study assessed the capacity of the 3T3 NRU cytotoxicity assay to identify specifically non-classified chemicals on the basis of the 2000 mg/kg b.w. threshold introduced by the EU CLP Regulation.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=139","lastUpdate":"Monday, October 12, 2020 - 09:07","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Industrial chemicals","endpoint":"Acute toxicity; Basal cytotoxicity","methodology":"In vitro; In silico; Integrated approach; Mixed","specificMethodologies":"Read-across/WoE; Cytotoxicity/cell viability assay; Analytical chemistry readout; Barrier/permeability/transport assay; Integrated testing strategy/battery; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2003-01","shortName":"NRU cytotoxicity","title":"Neutral red uptake for starting doses for acute oral toxicity","organisation":"ICCVAM/NICEATM - United States","description":"The in vitro Neutral Red Uptake (NRU) test method is a cell-based approach that assesses the cellular uptake of a dye in the presence of a particular substance. The protocols use normal human epidermal keratinocytes (NHK) and BALB/c 3T3 mouse fibroblasts (3T3). NHK cells are primary cells while 3T3 cells are an inmortal line. The method is used to assess basal cytotoxicity quantified through IC50 values (the concentration of test substance needed to decrease cell viability by 50% in the cell culture) by spectrophotometric measurments of the cellular uptake of NR dye. Assays that assess this type of toxicity look at how chemicals exert effects by disrupting structures and functions that are universal to all cells (e.g. cell membrane integrity, energy production and metabolism, transportation of molecules, secretion of molecules).This is opposed to assays that assess the effects of chemicals on specific molecular targets (such as receptors, ion channels etc.), lacking in the cells used in this method. Due to the fact that substances that produce injury and death are ultimately exerted at the cellular level, in vitro cytotoxiciicty assays may be also useful for the prediction of acute lethaly potency. The NRU IC50 concentration of a test substance in either 3T3 or NHK cells could be used to estimate the rodent LD50 value as a mean for predicting the starting doses for rodent acute oral toxicity studies.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Acute toxicity, Basal Cytotoxicity","yearReceived":"2003","generalComments":"The NICEATM/ECVAM Validation finalised/OECD Guidance Document","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=139","lastUpdate":"Monday, February 15, 2021 - 12:20","lastUpdateDate":"2021-02-15","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Acute toxicity; Basal cytotoxicity","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay; Analytical chemistry readout; Barrier/permeability/transport assay; Phototoxicity/photoreactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2010-03","shortName":"KeratinoSens","title":"KeratinoSens assay for the testing of skin sensitizers","organisation":"EURL ECVAM - European Union","description":"The KeratinoSens™ test method supports the discrimination between sensitizing and non-sensitizing chemicals. It addresses one of the biological mechanisms described under key event 2 (events in keratinocytes) of the skin sensitization Adverse Outcome Pathway by measuring the activation of the Keap1-Nrf2-ARE pathway. The Keap1-Nrf2-ARE regulatory pathway is reported to be a major regulator of cyto-protective responses to electrophile and oxidative stress by controlling the expression of detoxification, antioxidant and stress response enzymes and proteins. Small electrophilic substances such as skin sensitisers can act on the sensor protein Keap1 (Kelch-like ECH-associated protein 1), by e.g., covalent modification of its cysteine residue, resulting in its dissociation from the transcription factor Nrf2 (nucler factor-erythroid 12-related factor 2). The dissociated Nrf2 can then activate ARE-dependent genes such as those coding for phase II detoxifying enzymes. The KeratinoSens™ is performed using an immortalized adherent cell line derived from HaCaT human keratinocytes stably transfected with a selectable plasmid containing the luciferase gene under the transcriptional control of a constitutive promoter fused with an ARE element. The quantitative measurement by luminescence detection of the luciferase gene induction is used as an indicator of the activity of the Nrf2 transcription factor in cells following exposure to electrophilic test chemicals.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2010","generalComments":"The validation was performed externally between 2009 and 2010","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=155","lastUpdate":"Monday, October 12, 2020 - 08:55","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro; In chemico; Mixed","specificMethodologies":"Reporter gene assay; Chemical reactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2014-02","shortName":"H2AX ICW","title":"H2AX ICW method, gH2AX In cell western","organisation":"EURL ECVAM - European Union","description":"The method is an in vitro genotoxic 96-well plate format assay for the measurement of histone gH2AX phosphorylation, normally occurring after DSBs induction in different cell types. The use of the gH2AX global genotoxic biomarker coupled with the in cell western technique permit to determined simultaneously the cytotoxicity and the genotoxicity of any tested compound. The in cell western technique is an immunohistochemistry in situ (directly into the well) used in combination with infra-red fluorescence. The assay is proposed in early discovery phase of drug development for genotoxicity screening or as a substitute of the in vitro micronucleus test.","stepStage":"Submission > Receipt of presubmission","workflowStep":"Submission","workflowStage":"Receipt of presubmission","topic":"Genotoxicity/Mutagenicity","yearReceived":"2014","generalComments":"Presubmission assessment finalised. Method Not prioritised for validation","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:39","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_RECEIPT","applicationDomain":"Pharmaceutical","endpoint":"Genotoxicity","methodology":"In vitro","specificMethodologies":"HTS; Cytotoxicity/cell viability assay; Immunoassay/flow cytometry; Micronucleus/genotoxicity assay; Biomarker/DNA damage assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2017-01","shortName":"gH2AX/pH3","title":"gH2AX/pH3 biomarkers for the prediction of DNA damage","organisation":"EURL ECVAM - European Union","description":"The proposed method is based on gH2AX/pH3 biomarkers for the prediction of genotoxic potential of all kind of substances. The combination of the two biomarkers is proposed to detect early events in the DNA damage response and to discriminate structural and numerical chromosome damage. This assay is applicable to almost all cell types including cells of human origin. The assay use innovative techniques with a higher throughput than usual assays and potentially amenable to automation. The method is less prone to irrelevant positive results as compared to some of the current assays because is able to also discriminate the misleading cytotoxic chemicals.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Genotoxicity/Mutagenicity","yearReceived":"2017","generalComments":"Presubmission assessment finalised. Method Not prioritised for validation","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:26","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"Other","specificMethodologies":"Biomarker/DNA damage assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-08","shortName":"Greenscreen","title":"GreenScreen HC TM Genotoxicity Assay","organisation":"EURL ECVAM - European Union","description":"The Green Screen HCTM (GSHC) assay is an in vitro human cell-based genotoxicity test method intended to predict the in vivo genotoxic potential of chemicals. Specifically, the GSHC is a microplate format genotoxicity plus cytotoxicity screening assay which uses the DNA damage-inducible \"Growth Arrest and DNA Damage 45 alpha\" (GADD45a) - Green Fluorescent Protein (GFP) reporter gene, expressed in the p53-competent human lymphoblastoid TK6 cell line. The Submitter has proposed the test method for both regulatory and non-regulatory genotoxicity assessment: (A) for compound discovery and development screening applications; (B) as additional test to be used in Option2 under ICH S2(R1); (C) as stand-alone test alternative to the in vitro battery; (D) to support weight of evidence arguments in regulatory safety assessment of in vitro genotoxicity battery data - where genotoxicity data from other tests are conflicting.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Genotoxicity/Mutagenicity","yearReceived":"2009","generalComments":"The test method underwent an external (non EURL ECVAM-coordinated) validation study and all available information/data were submitted for a Retrospective Validation. Following consultation with EURL ECVAM network of regulators (PARERE - Preliminary Assessment of Regulatory Relevance), the test method did not progress to peer review.","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=132","lastUpdate":"Monday, October 12, 2020 - 10:06","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Genotoxicity","methodology":"In vitro; In silico; Mixed","specificMethodologies":"HTS; Reporter gene assay; Read-across/WoE; Cytotoxicity/cell viability assay; Integrated testing strategy/battery; Biomarker/DNA damage assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-09","shortName":"SkinEthic HCE","title":"Human Reconstructed Corneal Epithelium (HCE) Eye Irritation test","organisation":"EURL ECVAM - European Union","description":"The purpose of this assay was to evaluate the ocular irritation potential of chemicals for European Union labelling and classification, in order to discriminate non irritants from irritants, and to be used as an alternative to the traditional in vivo rabbit eye test method (OECD TG 405). The test uses the SkinEthic™ HCE model, a reconstructed human cornea-like epithelium (RhCE) consisting of a multilayered epithelium prepared from immortalized human corneal epithelial cell. It constitutes a three dimensional structure which reproduces the multi-layer organization of the human cornea. The test consists of a topical exposure of the neat test chemicals onto the Human Corneal Epithelium model HCE, followed by cell viability measurement.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Serious eye damage/Eye irritation","yearReceived":"2008","generalComments":"This test method was unable to comply fully with the acceptance criteria set by the validation management group. A revised SkinEthic™ HCE EIT test method was re-submitted for assessment by EURL ECVAM and formal ESAC peer review in October 2015 (See TM2015-03, SkinEthic-HCE-EIT).","protocolSop":"","lastUpdate":"Wednesday, October 21, 2020 - 16:27","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2011-10","shortName":"LuSens","title":"LuSens Assay","organisation":"EURL ECVAM - European Union","description":"The LuSens assay supports the discrimination between sensitizing and non-sensitizing chemicals. It is based on the same concepts as the OECD adopted KeratinoSens™. The LuSens assay addresses one of the biological mechanisms described under key event 2 (events in keratinocytes) of the skin sensitization Adverse Outcome Pathway by measuring the activation of the Keap1-Nrf2-ARE pathway. The Keap1-Nrf2-ARE regulatory pathway is reported to be a major regulator of cyto-protective responses to electrophile and oxidative stress by controlling the expression of detoxification, antioxidant and stress response enzymes and proteins. Small electrophilic substances such as skin sensitisers can act on the sensor protein Keap1 (Kelch-like ECH-associated protein 1), by e.g., covalent modification of its cysteine residue, resulting in its dissociation from the transcription factor Nrf2 (nucler factor-erythroid 12-related factor 2). The dissociated Nrf2 can then activate ARE-dependent genes such as those coding for phase II detoxifying enzymes. The LuSens assay is performed using genetically modified keratinocytes derived from HaCaT cells. It employs the reporter gene for luciferase under the control of an antioxidant response element (ARE) and hence monitors Nrf-2 transcription factor activity. The endpoint measurement is the up-regulation of the luciferase activity after 48 h incubation with test substance. This up-regulation is an indicator for the activation of the Keap1/Nrf2/ARE signaling pathway by ‘electrophilic stress' caused by cystein reactive substances.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2011","generalComments":"The Lu-Sens underwent an external catch-up validation study based on the performance standards for in vitro skin sensitisation ARE-NrF2 luciferase test methods (OECD 2015).","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=184","lastUpdate":"Monday, October 12, 2020 - 10:05","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro; In chemico; Mixed","specificMethodologies":"Reporter gene assay; Chemical reactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2014-06","shortName":"Sterlab RHE SIT","title":"Skin Irritation Test for the Prediction of Acute Skin Irritation of Chemicals With Sterlab RHE: 42 minutes application + 42 hours post-incubation","organisation":"EURL ECVAM - European Union","description":"The present test method is designed to predict and classify the skin irritant potential of chemicals according to chemical safety regulation, using STERLAB human reconstructed epidermis (RHE) model. The protocol is established for liquids, viscous and solid test substances. The relative viability of the treated tissues is measured at the end of the treatment exposure (42 minutes) followed by a post-exposure period (42 hours) using a cell viability test.","stepStage":"Submission > Assessment of full submission","workflowStep":"Submission","workflowStage":"Assessment of full submission","topic":"Skin irritation","yearReceived":"2014","generalComments":"","protocolSop":"","lastUpdate":"Thursday, April 2, 2026 - 13:22","lastUpdateDate":"2026-04-02","stage":"Test Submission","status":"Ongoing","code":"SUB_ASSESS","applicationDomain":"Cosmetics; Industrial chemicals","endpoint":"Skin irritation","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2009-06","shortName":"DPRA","title":"Direct Peptide Reactivity Assay","organisation":"EURL ECVAM - European Union","description":"The DPRA supports the discrimination between sensitising and non-sensitising chemicals. It measures in chemico the binding of test chemicals to model synthetic peptides containing either lysine or cysteine. Within the skin sensitization Adverse Outcome Pathway the covalent binding of electrophilic chemicals with nucleophilic sites of amino acids in skin proteins is postulated to be the molecular initiating event (MIE) (i.e. key event 1 – protein binding reactions) leading to skin sensitisation. In skin proteins many amino acids contain electron-rich groups capable of reacting with sensitisers. Lysine and cysteine are those most often quoted but others such as arginine, histidine, methionine and tyrosine can react with electrophilic chemicals.","stepStage":"Validation > Ongoing","workflowStep":"Validation","workflowStage":"Ongoing","topic":"Skin sensitisation","yearReceived":"2009","generalComments":"Validation finalised, ECVAM Recommendation published, OECD TG available","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=154","lastUpdate":"Monday, October 12, 2020 - 09:59","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"VAL_ONGO","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In chemico","specificMethodologies":"Binding/interaction assay; Chemical reactivity assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM1998-04","shortName":"In vitro mAbs","title":"In vitro production of monoclonal antibodies (hybridoma technique)","organisation":"EURL ECVAM - European Union","description":"Based on the conclusions and recommendations of ECVAM workshop report 23 (Marx et al, 1997, ATLA, 25 121-137) and a report on monoclonal antibody production (Hendriksen, 1998, ATLA 26, 523-540), the ESAC concluded that for all levels of monoclonal antibody production, scientifically acceptable in vitro methods (e.g. hybridoma techniques) are practicably available. These methods have been shown to be either better than, or equal to, the in vivo (ascites) production method in terms of antibody quality. Therefore, the in vivo production of monoclonal antibodies by the ascites method is no longer scientifically necessary, except in rare cases.","stepStage":"Peer-review > Finalised","workflowStep":"Peer-review","workflowStage":"Finalised","topic":"Human health","yearReceived":"1998","generalComments":"","protocolSop":"","lastUpdate":"Wednesday, October 21, 2020 - 16:10","lastUpdateDate":"2020-10-21","stage":"Validation","status":"Finalised","code":"VAL_PEER_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Human health — unspecified","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"AI-reviewed","threeR":"Replacement","literature":"Complete","verificationNote":""},{"id":"TM2012-04","shortName":"gEST","title":"Genomic Embryonic Stem cell Test method","organisation":"EURL ECVAM - European Union","description":"The method addresses to test human embryotoxicity and consequently predicts developmental effects on the basis of alterations of gene expression of cell differentiation. The method has showed a large potential discriminating weak embryotoxicants form non-embryotoxicants without loss of capability to detect strong embryotoxicants. The test method compares the relationships among alterations of gene expression in D3 cells and changes on viability on the same D3 mouse embryonic stem cells and 3T3 mouse using as parameters alterations on cell viability determined by the MTT test and alterations on gene expression determined by quantitative RT-PCR.","stepStage":"Submission > Stopped","workflowStep":"Submission","workflowStage":"Stopped","topic":"Reproductive toxicity, Embryotoxicity","yearReceived":"2012","generalComments":"Not considered for follow-up","protocolSop":"","lastUpdate":"Monday, October 12, 2020 - 08:44","lastUpdateDate":"2020-10-12","stage":"Test Submission","status":"Discontinued","code":"SUB_STOP","applicationDomain":"Mixed/general toxicology","endpoint":"Reproductive toxicity; Embryotoxicity","methodology":"In vitro","specificMethodologies":"Omics; Cytotoxicity/cell viability assay; Embryo/developmental model","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2005-02","shortName":"SHE 6.7 CTA","title":"Syrian hamster embryo cell transformation assay at pH 6.7","organisation":"EURL ECVAM - European Union","description":"The in vitro CTA using Syrian hamster embryonic (SHE) cells at pH 6.7 is aimed at detecting the carcinogenic potential of chemicals. The assay is based on the change of the phenotypic features of cells undergoing the first steps of the conversion from normal cells to neoplastic-like cell foci with oncogenic properties. Carcinogenesis is a complex multistage process by which normal cells are transformed into cancer cells characterised by an accumulation of changes at the cellular, genetic and epigenetic level. In vitro CTAs such as the SHE CTA have been shown to recapitulate a multistage process that closely models some stages of in vivo carcinogenesis. A minimum of four phenotypic stages appears to be involved in cell transformation. These include (from primary to fully malignant cells): a block in cellular differentiation, acquisition of immortality, characterised by unlimited lifespan, an aneuploidy karyotype and a decreased genetic stability; acquisition of tumorigenicity, which is closely associated with the in vitro phenotypes of foci formation, anchorage independent growth in semi-solid agar and autocrine growth factor production; full malignancy, including metastasis when the cells are injected into a suitable host, supporting the biological relevance of in vitro transformation to in vivo carcinogenicity. The assay is based on the change of the phenotypic features of cell colonies undergoing the first steps of the conversion from normal cells to neoplastic-like cells with oncogenic properties","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Carcinogenicity","yearReceived":"2005","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=136","lastUpdate":"Monday, October 12, 2020 - 09:10","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Carcinogenicity","methodology":"In vitro","specificMethodologies":"Embryo/developmental model; Cell transformation assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2005-03","shortName":"SHE 7.0 CTA","title":"Syrian hamster embryo cell transformation assay at pH 7.0","organisation":"EURL ECVAM - European Union","description":"The in vitro CTA using Syrian hamster embryonic (SHE) cells at pH 7.0 is aimed at detecting the carcinogenic potential of chemicals. The assay is based on the change of the phenotypic features of cells undergoing the first steps of the conversion from normal cells to neoplastic-like cell foci with oncogenic properties. Carcinogenesis is a complex multistage process by which normal cells are transformed into cancer cells characterised by an accumulation of changes at the cellular, genetic and epigenetic level. In vitro CTAs such as the SHE CTA have been shown to recapitulate a multistage process that closely models some stages of in vivo carcinogenesis. A minimum of four phenotypic stages appears to be involved in cell transformation. These include (from primary to fully malignant cells): a block in cellular differentiation, acquisition of immortality, characterised by unlimited lifespan, an aneuploidy karyotype and a decreased genetic stability; acquisition of tumorigenicity, which is closely associated with the in vitro phenotypes of foci formation, anchorage independent growth in semi-solid agar and autocrine growth factor production; full malignancy, including metastasis when the cells are injected into a suitable host, supporting the biological relevance of in vitro transformation to in vivo carcinogenicity. The assay is based on the change of the phenotypic features of cell colonies undergoing the first steps of the conversion from normal cells to neoplastic-like cells with oncogenic properties","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Carcinogenicity","yearReceived":"2005","generalComments":"","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=136","lastUpdate":"Monday, October 12, 2020 - 09:10","lastUpdateDate":"2020-10-12","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Mixed/general toxicology","endpoint":"Carcinogenicity","methodology":"In vitro","specificMethodologies":"Embryo/developmental model; Cell transformation assay","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2008-05","shortName":"hCLAT","title":"Human Cell Line Activation Test","organisation":"EURL ECVAM - European Union","description":"The h-CLAT supports the discrimination between sensitizing and non-sensitizing chemicals The h-CLAT quantifies in vitro changes in the expression of the CD86 and CD54 membrane phenotypic markers in a human monocytic leukemia cell line (THP-1 cells). THP-1 cells are monocyte-derived cells that have shown to produce DC-like responses following exposure to skin sensitising chemicals (e.g. upregulation of surface markes (e.g. CD86 and CD54) and cytokine production (e.g. TNF-α). The CD86 (a co-stimulatory molecule) and the CD54 (an adhesion molecule) are upregulated in activated Dendritic Cells (DC) and play a critical role in DC presentation of antigens to T cells (T-cell priming). By studying the potential of test chemicals to up-regulate markers of DC activation, the h-CLAT generates information addressing key event 3 (dendritic cell activation) of the skin sensitization Adverse Outcome Pathway.","stepStage":"Regulatory acceptance/Standards > Adopted/published","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Adopted/published","topic":"Skin sensitisation","yearReceived":"2008","generalComments":"Test Guideline has been adopted as TG442E in July 2016","protocolSop":"https://jeodpp.jrc.ec.europa.eu/ftp/jrc-opendata/EURL-ECVAM/datasets/DBALM/LATEST/online/dbalm.html?search=158","lastUpdate":"Wednesday, September 3, 2025 - 09:43","lastUpdateDate":"2025-09-03","stage":"Regulatory assessment","status":"Adopted","code":"REG_ADOPT","applicationDomain":"Cosmetics","endpoint":"Skin sensitisation","methodology":"In vitro","specificMethodologies":"Immunoassay/flow cytometry","review":"AI-reviewed","threeR":"Unknown","literature":"Complete","verificationNote":""},{"id":"TM2016-08","shortName":"ToxCast ER Pathway Model","title":"The ToxCast Estrogen Receptor Agonist Pathway Model","organisation":"ICCVAM/NICEATM - United States","description":"The ToxCast estrogen receptor (ER) pathway model is a mathematical model that combines the results from 18 high-throughput screening (HTS) assays from the ToxCast and Tox21 research programs. The HTS assays measure ER binding, dimerization, chromatin binding, transcriptional activation and ER-dependent cell proliferation. The model uses activity patterns across the in vitro assays to predict whether a chemical is an ER agonist or antagonist, or is otherwise influencing the assays through a manner dependent on the physics and chemistry of the technology platform (“assay interference”). The output of the model provides an area under the curve (AUC) value for the potential of a chemical to cause ER agonism, normalized with respect to the positive control chemical, estradiol.","stepStage":"","workflowStep":"","workflowStage":"","topic":"Reproductive toxicity, Endocrine disruption","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Monday, February 15, 2021 - 12:18","lastUpdateDate":"2021-02-15","stage":"Regulatory assessment","status":"Adopted","code":"UNKNOWN_UNKNOWN","applicationDomain":"Mixed/general toxicology","endpoint":"Endocrine disruption","methodology":"Integrated approach; In vitro; In silico; Mixed","specificMethodologies":"HTS; Reporter gene assay; Binding/interaction assay; Integrated testing strategy/battery","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":""},{"id":"TM2016-07","shortName":"EASA","title":"The Electrophilic Allergen Screening Assay for the Detection of Substances Causing Allergic Contact Dermatitis","organisation":"ICCVAM/NICEATM - United States","description":"The EASA consists of 2 simple chemical tests that assess the ability of electrophilic substances to bind to protein by measuring the depletion of free protein surrogates caused by covalent binding of the protein surrogate to the test substance. In the first test, depletion of 4-nitrobenzothiol (NBT), the protein surrogate for soft electrophiles, is measured by the loss of absorbance at 324 nm at 25oC for up to 2 hours. If depletion of NBT ≥ 30%, the test substance is classified as a sensitizer. If depletion of NBT < 30%, confirmation tests must be performed. To confirm the result, the test substance is retested at twice the initial concentration of test substance and/or by increasing the reaction time to 4 hours. If depletion of NBT < 30%, then the second test is performed. In the second test, depletion of pyridoxylamine (PDA), the protein surrogate for hard electrophiles, is measured by the loss of absorbance at 324 nm at 25oC for up to 2 hours. If depletion of PDA ≥ 30%, the test substance is classified as a sensitizer. If depletion of PDA < 30%, confirmation tests, analogous to those with NBT, must be performed. For test substances that interfere with the absorbance of PDA, the loss of PDA is assessed by measuring the decrease in fluorescence at excitation wavelength=324 nm and emission wavelength=398 nm at 25°C for up to 2 hours.","stepStage":"Validation > Planning","workflowStep":"Validation","workflowStage":"Planning","topic":"Skin sensitisation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Monday, February 15, 2021 - 13:03","lastUpdateDate":"2021-02-15","stage":"Validation","status":"Ongoing","code":"VAL_PLAN","applicationDomain":"Mixed/general toxicology","endpoint":"Skin sensitisation","methodology":"In chemico","specificMethodologies":"HTS; Analytical chemistry readout; Binding/interaction assay; Chemical reactivity assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"External expert evidence shows completion of the EASA multilaboratory validation, followed by a final NICEATM validation report in 2025 and peer-reviewed validation publication in 2026. This supports External_evidence_step_stage = VAL_FINAL. TSAR source-copy lifecycle/status fields are intentionally left unchanged; any source snapshot refresh should be handled through the source-refresh workflow."},{"id":"TM2016-06","shortName":"MAT","title":"Monocyte Activation Test","organisation":"BraCVAM - Brazil","description":"MAT is intended to determine pyrogenic contamination of injectable products. The aim of this activity is to demonstrate new appplications of MAT, such as, its use on biological products (hyperimmune sera, vaccines, blood products), medical devices, nanomaterials and Non-Endotoxin Pyrogens (NEPs). Once demonstrated, this test may replace Rabbit Pyrogen Test (RPT) or enter together wit Bacterial Endotoxin Test (BET). In this last case, since BET is negative, it is needed to perform MAT. If BET is positive, then, stop. The assay is based upon the Human mechanism of fever. The products is kept in contact with human blood and the cytokines (IL-1b and/or IL-6) are measured by commercial ELISA,","stepStage":"Regulatory acceptance/Standards > Drafting of new regulatory standard/guideline","workflowStep":"Regulatory acceptance/Standards","workflowStage":"Drafting of new regulatory standard/guideline","topic":"Quality control of vaccines, Airborne pyrogens","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, March 6, 2018 - 07:57","lastUpdateDate":"2018-03-06","stage":"Regulatory assessment","status":"Acceptance pending","code":"REG_DRAFT","applicationDomain":"Pharmaceutical; Medical devices","endpoint":"Vaccine quality control; Pyrogenicity","methodology":"Ex vivo","specificMethodologies":"Immunoassay/flow cytometry; Ex vivo/tissue-based assay; Integrated testing strategy/battery","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"Expert review: Later evidence documents continued MAT validation/application expansion and subsequent European Pharmacopoeia progress. TSAR source-copy lifecycle/status fields are intentionally left unchanged; lifecycle/status updates should be handled through the source-refresh workflow."},{"id":"TM2016-05","shortName":"HET-CAM","title":"Hen’s Egg Test – Chorio-Allantoic Membrane","organisation":"BraCVAM - Brazil","description":"This method is intented to enter a battery of assays to replace rabbits on Eye Irritation Test, as indication of non-irritant substances and a Bottom-Up strategy. Leghorn SPF eggs are used. The test substance is applied to the surface of the CAM. The CAM is evaluated by the appearance of following: congestion (hyperemia), hemorrhage (bleeding), and coagulation (intra- and extravascular). In Brazil, HET-CAM is already accepted by ANVISA as a screening test, but nor for regulatory purposes.","stepStage":"","workflowStep":"","workflowStage":"","topic":"Serious eye damage/Eye irritation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, March 6, 2018 - 07:57","lastUpdateDate":"2018-03-06","stage":"Regulatory assessment","status":"Unknown","code":"UNKNOWN_UNKNOWN","applicationDomain":"Mixed/general toxicology","endpoint":"Eye irritation/Serious eye damage","methodology":"In vivo","specificMethodologies":"Embryo/developmental model; In vivo reduction/refinement assay","review":"Expert-reviewed","threeR":"Reduction","literature":"Partial","verificationNote":"External expert evidence documents the 2015 BraCVAM prospective validation and later OECD IATA status for HET-CAM. TSAR source-copy lifecycle/status fields are intentionally left unchanged; any lifecycle/status refresh should be handled through the source-refresh workflow."},{"id":"TM2016-04","shortName":"MCTT HCE™-EIT","title":"A new in vitro eye irritation test with a 3D-reconstructed human cornea epithelium, MCTT HCE™","organisation":"KoCVAM - Republic of Korea","description":"The MCTT HCE™-EIT is a test method identifying eye irritation potential of chemicals using reconstructed human corneal epithelium (RhCE) prepared from primary human corneal cells.","stepStage":"Submission > Assessment finalised","workflowStep":"Submission","workflowStage":"Assessment finalised","topic":"Serious eye damage/Eye irritation","yearReceived":"2016","generalComments":"","protocolSop":"","lastUpdate":"Tuesday, March 6, 2018 - 07:57","lastUpdateDate":"2018-03-06","stage":"Validation","status":"Ongoing","code":"SUB_FINAL","applicationDomain":"Mixed/general toxicology","endpoint":"Eye irritation/Serious eye damage","methodology":"In vitro","specificMethodologies":"Organoid/3D tissue model; Cytotoxicity/cell viability assay","review":"Expert-reviewed","threeR":"Replacement","literature":"Partial","verificationNote":"External expert evidence shows subsequent successful MCTT HCE™ validation and OECD validation peer review, followed by inclusion in OECD TG 492. TSAR source-copy lifecycle/status fields are intentionally left unchanged; any lifecycle/status refresh should be handled through the source-refresh workflow."}];
